\begin{restatable}[Main Theorem]{theorem}{MAINTHEOREM}
 \label{thm:main}
 Let Assumptions~\ref{ass:lipschitz_constant}, \ref{ass:lower_bound}, and \ref{ass:stochastic_variance_bounded} hold. Consider any \algname{SGD} method represented by \emph{computation tree} $G = (V, E)$. Let $\{x^k\}_{k \geq 0}$ be a \emph{main branch} of $G$ and $\{(z^k, \xi^k)\}_{k \geq 0}$ be the corresponding \emph{auxiliary sequence} (see Def.~\ref{def:branch}) that satisfy the following conditions: \\
 \textnormal{\bf Condition 1:} For all $k \geq 0,$ $\xi^k$ is statistically independent of 
 $\{(x^{i+1}, z^{i+1}, \xi^i)\}_{i=0}^{k-1}.$ \\
%   $(x^k, z^k, \xi^0, \dots, \xi^{k-1}).$ \\
 \textnormal{\bf Condition 2:} The representation of $z^k$ is contained within that of $x^k$, i.e.,
     $
     \textstyle \textnormal{repr}(z^k) \subseteq \textnormal{repr}(x^k)
     $
     for all $k \geq 0.$ Equivalently, all stochastic gradients used in the computation of $z^k$ are also utilized in calculating $x^k$. \\
 \textnormal{\bf Condition 3:} There exists a constant $R \in [0, \infty]$ such that
     $
     \textstyle \textnormal{dist}(x^k, z^k) \le R
     $
     for all $k \geq 0.$ 
     % Equivalently, we can define $R \eqdef \sup_{k \geq 0} \textnormal{dist}(x^k, z^k).$ \\
 Then $\frac{1}{K}\sum_{k=0}^{K-1}\Exp{\|\nabla f(x^k)\|^2} \le \varepsilon$ for all 
