\section{Proof of Theorem~\ref{thm:main}}
\subsection{Proof technique and reasons for choosing the conditions}
\label{sec:novel}
Before we state the main theorem and provide the proof, let us explain the intuition, the novelty, and how we identified the conditions of the theorem. The proof of the result is given in Section~\ref{sec:proof} and is relatively compact. We believe that the simplicity of our result, together with its ability to unify methods, constitutes an important contribution to the optimization community. While the initial part of the proof follows the same structure as in most related works, starting from \eqref{eq:tyfEHNd}, our treatment of the staleness term $\|x^k - z^k\|,$ which naturally arises from the step $x^{k+1} = x^k - \gamma \nabla f(z^k; \xi^k),$ is novel. 

After many attempts to develop a universal theory, let us illustrate how we arrived at our conditions. Looking at Figure~\ref{fig:fork}, which provides all possible relations between $x^k$ and $z^k,$ one can easily get 
% $$\|x^k - z^k\| = \gamma \|{\color{mydarkblue} \sum_{i=p}^{k - 1} \nabla f(z^i;\xi^i)} - {\color{mydarkred} \sum_{(w,\xi) \in S^k} \nabla f(w; \xi)}\|.$$
$$\norm{x^k - z^k} = \gamma \norm{{\color{mydarkblue} \sum_{i=p}^{k - 1} \nabla f(z^i;\xi^i)} - {\color{mydarkred} \sum_{(w,\xi) \in S^k} \nabla f(w; \xi)}}.$$ First, we noticed that any reasonable method should utilize ${\color{mydarkred} \sum_{(w,\xi) \in S^k} \nabla f(w; \xi)}$ in the computation of $z^k$ before applying $\nabla f(z^k; \xi^k)$ (see the previous discussion about Condition 2 in Section~\ref{sec:main}). This implies ${\color{mydarkred} \{(w; \xi)\}_{(w,\xi) \in S^k}} \subseteq {\color{mydarkblue} \{(z^i; \xi^i)\}_{i = p}^{k-1}},$ leading to the following \emph{identity}:
% $\|x^k - z^k\| = \gamma \|\sum_{j \in \bar{S}^k} \nabla f(z^j;\xi^j)\|$ 
$$\norm{x^k - z^k} = \gamma \norm{\sum_{j \in \bar{S}^k} \nabla f(z^j;\xi^j)}$$
for some set $\bar{S}^k \subseteq {\color{mydarkblue} \{p, \dots, k - 1\}}$ such that $\bar{S}^k \cup S^k = {\color{mydarkblue} \{p, \dots, k - 1\}}.$ The \emph{identity} says that the distance is roughly proportional to the number $\abs{\bar{S}^k}$ of stochastic gradients applied after $x^p$ and before $z^k,$ which is \emph{tightly} bounded by the tree distance from $x^k$ to the common ancestor $x^p,$ i.e., it is bounded by $\abs{{\color{mydarkblue} \{p, \dots, k - 1\}}}$ since $\bar{S}^k \subseteq {\color{mydarkblue} \{p, \dots, k - 1\}}.$
% or by the tree distance $\textnormal{dist}(x^k, z^k)$ (see Definition~\ref{def:dist}). 

Under Condition 2, notice that $\abs{{\color{mydarkblue} \{p, \dots, k - 1\}}} = \max\{\abs{{\color{mydarkblue} \{p, \dots, k - 1\}}}, \abs{S^k}\} =: \textnormal{dist}(x^k, z^k),$ where we use $S^k \subseteq {\color{mydarkblue} \{p, \dots, k - 1\}}$ and Definition~\ref{def:dist}. Thus, to get a bound for $\|x^k - z^k\|,$ it is natural to introduce Condition 3, which allows us to conclude that $\abs{\bar{S}^k} \leq \textnormal{dist}(x^k, z^k) \leq R.$ It remains to use classical mathematical tools to obtain 
% $\mathbb{E} \|x^k - z^k\|^2 \leq 2 \gamma^2 R \sum_{j=k - R}^{k - 1} \mathbb{E} \|\nabla f(z^j)\|^2 + 2 \gamma^2 R \sigma^2,$ 
$$\Exp{\norm{x^k - z^k}^2} \leq 2 \gamma^2 R \sum_{j=k - R}^{k - 1} \Exp{\norm{\nabla f(z^j)}^2} + 2 \gamma^2 R \sigma^2,$$ 
where the first term will be canceled by the corresponding term $- \frac{\gamma}{4} \Exp{\norm{\nabla f(z^k)}^2}$ from \eqref{eq:KexjcUoRoQTYKqIDO}.

\subsection{Full proof}
\label{sec:proof}
\MAINTHEOREM*

\begin{proof}
  As the beginning, the analysis is standard. Using Assumption~\ref{ass:lipschitz_constant}, we have
  \begin{align*}
    f(x^{k+1}) \leq f(x^k) - \gamma \inp{\nabla f(x^k)}{\nabla f(z^k;\xi^k)} + \frac{L \gamma^2}{2} \norm{\nabla f(z^k;\xi^k)}^2
  \end{align*}
  for $x^{k+1} = x^{k} - \gamma \nabla f(z^k;\xi^k).$ Due to Condition 1 of the theorem and the variance decomposition equality,
  \begin{align*}
    &\ExpSub{k}{f(x^{k+1})} 
    \leq f(x^k) - \gamma \inp{\nabla f(x^k)}{\nabla f(z^k)} + \frac{L \gamma^2}{2} \ExpSub{k}{\norm{\nabla f(z^k;\xi^k)}^2} \\
    &\quad= f(x^k) - \gamma \inp{\nabla f(x^k)}{\nabla f(z^k)} + \frac{L \gamma^2}{2} \norm{\nabla f(z^k)}^2 + \frac{L \gamma^2}{2} \ExpSub{k}{\norm{\nabla f(z^k;\xi^k) - \nabla f(z^k)}^2} \\
    &\quad\leq f(x^k) - \gamma \inp{\nabla f(x^k)}{\nabla f(z^k)} + \frac{L \gamma^2}{2} \norm{\nabla f(z^k)}^2 + \frac{L \gamma^2 \sigma^2}{2},
  \end{align*}
  where $\ExpSub{k}{\cdot}$ is the expectation conditioned on $(x^k, z^k).$
  In the last inequality, we use Assumption~\ref{ass:stochastic_variance_bounded}. Rewriting the dot product and using $\gamma \leq \frac{1}{2 L}$, we obtain
  \begin{align}
    &\ExpSub{k}{f(x^{k+1})} \nonumber \\
    &\leq f(x^k) - \frac{\gamma}{2} \left(\norm{\nabla f(x^k)}^2 + \norm{\nabla f(z^k)}^2 - \norm{\nabla f(x^k) - \nabla f(z^k)}^2\right) + \frac{L \gamma^2}{2} \norm{\nabla f(z^k)}^2 + \frac{L \gamma^2 \sigma^2}{2} \nonumber \\
    &\leq f(x^k) - \frac{\gamma}{2}\norm{\nabla f(x^k)}^2 - \frac{\gamma}{4} \norm{\nabla f(z^k)}^2 + \frac{\gamma}{2} \norm{\nabla f(x^k) - \nabla f(z^k)}^2 + \frac{L \gamma^2 \sigma^2}{2}. \label{eq:KexjcUoRoQTYKqIDO}
  \end{align}
  In the rest of the proof, we focus on $\norm{\nabla f(x^k) - \nabla f(z^k)}^2.$ Using Assumption~\ref{ass:lipschitz_constant}, we obtain
  \begin{align}
    \label{eq:tyfEHNd}
    &\norm{\nabla f(x^k) - \nabla f(z^k)}^2 \leq L^2 \norm{x^k - z^k}^2.
  \end{align}
  Notice that there exist $p \in \{0, \dots, k\}$ and the closest common ancestor $x^{p}$ such that 
  \begin{align*}
    x^k = x^{p} - \gamma \sum_{i=p}^{k - 1} \nabla f(z^i;\xi^i) = x^0 -\gamma \sum_{i=0}^{p - 1} \nabla f(z^i; \xi^i) - \gamma \sum_{i=p}^{k - 1} \nabla f(z^i;\xi^i)
  \end{align*}
  and 
  \begin{align*}
    z^k = x^{p} - \gamma \sum_{(w,\xi) \in S^k} \nabla f(w; \xi) = x^0 -\gamma \sum_{i=0}^{p - 1} \nabla f(z^i; \xi^i) - \gamma \sum_{(w,\xi) \in S^k} \nabla f(w; \xi),
  \end{align*}
  where $S^k$ is the set of points and random variables used to compute $z^k$ starting from $x^{p}$ (see Figure~\ref{fig:fork}). Moreover, due to Condition 3, we have $\textnormal{dist}(x^{k}, z^{k}) \leq \max\{k - p, \abs{S^k}\} \leq R,$ meaning $p \geq k - R.$ In total,
  \begin{align}
    \label{eq:VIHiAoGKxHvVihzN}
    k \geq p \geq k - R,
  \end{align}
  which we use later. Condition 2 assumes  
  \begin{align*}
    &\textnormal{repr}(z^k) \eqdef \underbrace{\{(z^i; \xi^i)\}_{i = 0}^{p - 1}}_{A} \uplus \underbrace{\{(w; \xi)\}_{(w,\xi) \in S^k}}_{C} \\
    &\subseteq \textnormal{repr}(x^k) \eqdef \underbrace{\{(z^i; \xi^i)\}_{i = 0}^{p - 1}}_{A} \uplus \underbrace{\{(z^i; \xi^i)\}_{i = p}^{k-1}}_{B},
  \end{align*}
  where $\uplus$ is the multiset union operation. Thus 
  \begin{align*}
    \underbrace{\{(w; \xi)\}_{(w,\xi) \in S^k}}_{C} \subseteq \underbrace{\{(z^i; \xi^i)\}_{i = p}^{k-1}}_{B}
  \end{align*}
  and
  \begin{align}
    \label{eq:ITXwDTcpKnui}
    x^k - z^k = - \gamma \left(\sum_{i=p}^{k - 1} \nabla f(z^i;\xi^i) - \sum_{(w,\xi) \in S^k} \nabla f(w; \xi)\right) = - \gamma \sum_{j \in \bar{S}^k} \nabla f(z^j;\xi^j),
  \end{align}
  where $\bar{S}^k$ is a set such that $\bar{S}^k \subseteq \{p, \dots, k - 1\}.$ 
  % Moreover, due to Condition 3, we get $p \leq R.$
  % \begin{align}
  %   \label{eq:kOUVqt}
  %   \abs{\bar{S}^k} \leq R
  % \end{align}
  % due to Condition 3. We will use \eqref{eq:kOUVqt} later. 
  Substituting \eqref{eq:ITXwDTcpKnui} to \eqref{eq:tyfEHNd},
  \begin{align*}
    &\norm{\nabla f(x^k) - \nabla f(z^k)}^2 \leq L^2 \gamma^2 \norm{\sum_{j \in \bar{S}^k} \nabla f(z^j;\xi^j)}^2.
  \end{align*}
  % Next, using the variance decomposition equality, we get
  Next, using Young's inequality $\norm{x + y}^2 \leq 2 \norm{x}^2 + 2 \norm{y}^2$ for all $x, y \in \R^d$, we get
  \begin{align*}
    &\Exp{\norm{\nabla f(x^k) - \nabla f(z^k)}^2} \leq 2 L^2 \gamma^2 \Exp{\norm{\sum_{j \in \bar{S}^k} \nabla f(z^j)}^2} + 2 L^2 \gamma^2 \Exp{\norm{\sum_{j \in \bar{S}^k} (\nabla f(z^j;\xi^j) - \nabla f(z^j))}^2}.
  \end{align*}
  % Since $\{\xi^k\}_{k \geq 0}$ are mutually independent (Condition 1) and using Assumption~\ref{ass:stochastic_variance_bounded},
  Since $\xi^j$ is statistically independent of 
  $\{(x^{i+1}, z^{i+1}, \xi^i)\}_{i=0}^{j-1}$
%   $(z^j, \xi^0, \dots, \xi^{j - 1})$ 
  for all $j \in \bar{S}^k$ (Condition 1) and using Assumption~\ref{ass:stochastic_variance_bounded},
  % Note that $\bar{S}^k = \{i_{1}, \dots, i_{\ell}\}$ for some $\ell \leq k - p$ and $i_{1} < \dots < i_{\ell}.$ For all $m > j,$ consider
  % \begin{align*}
  %   &\ExpSub{\bar{S}^k}{\inp{\nabla f(z^{i_m};\xi^{i_m}) - \nabla f(z^{i_m})}{\nabla f(z^{i_j};\xi^{i_j}) - \nabla f(z^{i_j})}} \\
  %   &=\ExpSub{\bar{S}^k}{\ExpSub{\xi^{i_m}}{\inp{\nabla f(z^{i_m};\xi^{i_m}) - \nabla f(z^{i_m})}{\nabla f(z^{i_j};\xi^{i_j}) - \nabla f(z^{i_j})}}}.
  % \end{align*}
  % We now ``freeze'' every random variance except $\xi^{i_m}.$ In this case, vectors $z^{i_m}$ and $z^{j_m}$ are deterministic due to Condition 1. Therefore
  % Let us show that vector $z^{i_j}$ is also deterministic if we ``freeze'' $\xi^{i_m}.$ Using a contradiction argument, assume that $z^{i_j}$ is not deterministic. We know that $x^{i_m}$ depends on $z^{i_j}$ because $i_m > i_j.$ Thus $x^{i_m}$ is random and non-deterministic, which contradicts the argument from the previous paragraph. Therefore
  % \begin{align*}
  %   &\ExpSub{\bar{S}^k}{\inp{\nabla f(z^{i_m};\xi^{i_m}) - \nabla f(z^{i_m})}{\nabla f(z^{i_j};\xi^{i_j}) - \nabla f(z^{i_j})}} = 0,
  % \end{align*}
  % and 
  \begin{align*}
    \Exp{\norm{\nabla f(x^k) - \nabla f(z^k)}^2} 
    &\leq 2 L^2 \gamma^2 \Exp{\norm{\sum_{j \in \bar{S}^k} \nabla f(z^j)}^2} + 2 L^2 \gamma^2 \abs{\bar{S}^k} \sigma^2 \\
    &\overset{\textnormal{Jensen's ineq.}}{\leq} 2 L^2 \gamma^2 \abs{\bar{S}^k} \sum_{j \in \bar{S}^k} \Exp{\norm{\nabla f(z^j)}^2} + 2 L^2 \gamma^2 \abs{\bar{S}^k} \sigma^2.
    % &\leq L^2 \gamma^2 \abs{\bar{S}^k} \sum_{j \in \bar{S}^k} \Exp{\norm{\nabla f(z^j)}^2} + L^2 \gamma^2 \abs{\bar{S}^k} \sigma^2
  \end{align*}
  Due to $\bar{S}^k \subseteq \{p, \dots, k - 1\}$ and \eqref{eq:VIHiAoGKxHvVihzN}:
  \begin{align*}
    \Exp{\norm{\nabla f(x^k) - \nabla f(z^k)}^2} 
    &\leq 2 L^2 \gamma^2 R \sum_{j=k - R}^{k - 1} \Exp{\norm{\nabla f(z^j)}^2} + 2 L^2 \gamma^2 R \sigma^2.
  \end{align*}
  Substituting this inequality to \eqref{eq:KexjcUoRoQTYKqIDO} and taking the full expectation, we obtain
  \begin{align}
    \Exp{f(x^{k+1})}
    &\leq \Exp{f(x^k)} - \frac{\gamma}{2}\Exp{\norm{\nabla f(x^k)}^2} - \frac{\gamma}{4} \Exp{\norm{\nabla f(z^k)}^2} + \frac{L \gamma^2 \sigma^2}{2} \nonumber \\
    &\quad + \frac{\gamma}{2} \left(2 L^2 \gamma^2 R \sum_{j=k - R}^{k - 1} \Exp{\norm{\nabla f(z^j)}^2} + 2 L^2 \gamma^2 R \sigma^2\right) \nonumber \\
    &\leq \Exp{f(x^k)} - \frac{\gamma}{2}\Exp{\norm{\nabla f(x^k)}^2} - \frac{\gamma}{4} \Exp{\norm{\nabla f(z^k)}^2} + L \gamma^2 \sigma^2 \nonumber \\
    &\quad + L^2 \gamma^3 R \sum_{j=k - R}^{k - 1} \Exp{\norm{\nabla f(z^j)}^2} \label{eq:icrcqHMvMJ}
  \end{align}
  because $\gamma \leq \frac{1}{2 R L}.$ Note that $\sum_{k = 0}^{K - 1} \sum_{j=k - R}^{k - 1} \Exp{\norm{\nabla f(z^j)}^2} \leq R \sum_{k = 0}^{K - 1} \Exp{\norm{\nabla f(z^k)}^2}.$ Thus, summing \eqref{eq:icrcqHMvMJ} for $k = 0, \dots, K - 1$ and substituting $f^*,$
  \begin{align*}
    \Exp{f(x^{K}) - f^*}
    &\leq f(x^0) - f^* - \frac{\gamma}{2} \sum_{k = 0}^{K - 1}\Exp{\norm{\nabla f(x^k)}^2} - \frac{\gamma}{4} \sum_{k = 0}^{K - 1} \Exp{\norm{\nabla f(z^k)}^2} + K L \gamma^2 \sigma^2 \nonumber \\
    &\quad + L^2 \gamma^3 R^2 \sum_{k = 0}^{K - 1} \Exp{\norm{\nabla f(z^k)}^2} \\
    &\leq f(x^0) - f^* - \frac{\gamma}{2} \sum_{k = 0}^{K - 1}\Exp{\norm{\nabla f(x^k)}^2} + K L \gamma^2 \sigma^2
  \end{align*}
  because $\gamma \leq \frac{1}{2 L R}.$ Finally, since $\Exp{f(x^{K}) - f^*} \geq 0,$
  \begin{align*}
    \frac{1}{K}\sum_{k = 0}^{K - 1}\Exp{\norm{\nabla f(x^k)}^2} \leq \frac{2 \Delta}{K \gamma} + 2 L \gamma \sigma^2.
  \end{align*}
  It is left to use that $\gamma = \min\{\frac{1}{2 L}, \frac{1}{2 R L}, \frac{\varepsilon}{4 \sigma^2 L}\}$ and the bound on $K$ from the theorem statement.
\end{proof}

