\section{Detailed Description of Algorithms and Iteration Rates}
\label{sec:algorithms}
In this section, we provide a detailed description together with theoretical analysis of the algorithms from the main part.
\subsection{\algname{Vanilla SGD}}
\label{sec:vanilla_sgd}
We start we the celebrated \algname{Vanilla SGD} algorithm, which formally can be implemented in the following way:
\begin{algorithm}[H]
  \caption{\algname{Vanilla SGD}}
  \label{alg:vanilla_sgd}
  \begin{algorithmic}[1]
      \STATE \textbf{Input:} starting point $w^0 \in \R^d$, step size $\gamma > 0$
      \FOR{$k = 0, 1, 2, \dots$}
          \STATE Sample $\eta^k \sim \mathcal{D}_{\xi}$ \hfill ($\{\eta^k\}$ are i.i.d.)
          \STATE Compute stochastic gradient $\nabla f(w^k; \eta^k)$
          \STATE Update $w^{k+1} = w^k - \gamma \nabla f(w^k; \eta^k)$
      \ENDFOR
  \end{algorithmic}
\end{algorithm}

The corresponding computation tree can defined by the recursion
\begin{align}
  \label{eq:ksGyF}
  w^{k+1} = w^k - \gamma \nabla f(w^k; \eta^k)
\end{align}
for all $k \geq 0.$

\begin{figure}[h]
  \centering
  \includegraphics[page=10,width=0.5\textwidth]{./graphs/graphs_new.pdf}
  \caption{The computation tree of \algname{Vanilla SGD}}
  \label{fig:sgd_graph}
\end{figure}

While the iteration rate of \algname{Vanilla SGD} is well-known \citep{lan2020first}, we prove its convergence using our new framework for clarity.
\begin{theorem}
  Let Assumptions~\ref{ass:lipschitz_constant}, \ref{ass:lower_bound}, and \ref{ass:stochastic_variance_bounded} hold. Consider the computation tree \eqref{eq:ksGyF} of \algname{Vanilla SGD}. Then, $\{x^k\}_{k \geq 0}$ is a main branch with $x^k = w^k$, $\{(z^k, \xi^k)\}_{k \geq 0}$ is the corresponding auxiliary sequence with $(z^k, \xi^k) = (w^k, \eta^k)$ (see Def.~\ref{def:branch}), and $\frac{1}{K}\sum_{k=0}^{K-1}\Exp{\|\nabla f(x^k)\|^2} \le \varepsilon$ for all 
  $$
  K \geq \frac{4 L \Delta}{\varepsilon} + \frac{8 \sigma^2 L \Delta}{\varepsilon^2}.
  $$
  with step size $\gamma = \min\{\frac{1}{2 L}, \frac{\varepsilon}{4 \sigma^2 L}\}.$
\end{theorem}

\begin{proof}
  Indeed, $\{x^k\}_{k \geq 0}$ and $\{(z^k, \xi^k)\}_{k \geq 0}$ satisfy Def.~\ref{def:branch} (see Fig.~\ref{fig:sgd_graph}). Moreover, all conditions of Theorem~\ref{thm:main} are fulfilled: Condition 1 holds because the sequence $\{\eta^k\}$ is i.i.d., we have $\textnormal{repr}(z^k) = \textnormal{repr}(x^k)$ since $x^k = z^k$, and consequently, $R = \sup_{k \geq 0} \textnormal{dist}(x^k, z^k) = 0$.
\end{proof}

