\subsection{\algname{Rennala SGD}}
\label{sec:rennala_sgd}
We now apply Theorem~\ref{thm:main} to \algname{Rennala SGD}. The iteration rate of \algname{Rennala SGD} is also well-known \citep{tyurin2023optimal}, but we provide a proof for completness. \algname{Rennala SGD} can be formally described as follows:
\begin{algorithm}[H]
  \caption{\algname{Rennala SGD} \citep{tyurin2023optimal}}
  \label{alg:rennala}
  \begin{algorithmic}[1]
      \STATE \textbf{Input:} point $w^0 \in \R^d$, stepsize $\gamma > 0$, batch size $B\in \N$
      \STATE Workers start computing stochastic gradients at $w^0$
      \FOR{$k = 0, \dots, K - 1$}
          \STATE $g^k_i = 0$ for all $i \in [n]$; $b=0$
          \WHILE{$b < B$}
              \STATE Wait for the moment when stochastic gradient is computed by worker
              \STATE Gradient $\nabla f(w^{k - \delta}; \eta)$ is computed by worker $i,$ $\quad \eta \sim \mathcal{D}_{\xi}$ \\
              \IF{$\delta = 0$}
                  \color{black}
                  \STATE Update $g^k_i = g^k_i + \nabla f(w^{k - \delta}; \eta)$ locally in worker $i$
                  \STATE $b=b+1$
              \ELSE
                  \STATE Ignore $\nabla f(w^{k - \delta}; \eta)$
              \ENDIF
              \STATE Worker $i$ begins calculating gradient at $w^{k}$ \\ 
          \ENDWHILE
          \STATE Aggregate: $g^k = \sum_{i=1}^n g^k_i$ \hfill (e.g, via \texttt{AllReduce})
          \STATE Update: $w^{k+1} = w^{k} - \gamma g^k$
      \ENDFOR
  \end{algorithmic}
\end{algorithm}

To use Theorem~\ref{thm:main}, we have to construct the computation tree of \algname{Rennala SGD}. It can be constructed in the following way:
\begin{alignat}{2}
  x^{1}   &= x^{0} - \gamma \nabla f(x^0;\xi^{0}), \quad  &\dots,\quad & x^{B}   = x^{B-1} - \gamma \nabla f(x^0;\xi^{B-1}), \label{eq:dOBxW}\\
  x^{B+1} &= x^{B} - \gamma \nabla f(x^{B};\xi^{B}), \quad &\dots,\quad & x^{2 B} = x^{2 B-1} - \gamma \nabla f(x^B;\xi^{2 B - 1}), \quad \dots \nonumber,
\end{alignat}
where $\{\xi^i\}$ are i.i.d.~from $\mathcal{D}_{\xi}.$ See also a visualization in Figure~\ref{fig:minibatch_sgd_graph}. One can easily show that $w^{1} = x^{0}, w^{1} = x^{B}, w^{2} = x^{2 B},$ etc.

\begin{figure}[h]
  \centering
  \includegraphics[page=11,width=0.6\textwidth]{./graphs/graphs_new.pdf}
  \caption{The computation tree of \algname{Rennala SGD}}
  \label{fig:minibatch_sgd_graph}
\end{figure}

\begin{theorem}
  Let Assumptions~\ref{ass:lipschitz_constant}, \ref{ass:lower_bound}, and \ref{ass:stochastic_variance_bounded} hold. Consider the computation tree \eqref{eq:dOBxW} of \algname{Rennala SGD}, then $\{x^k\}_{k \geq 0}$ is a main branch, $\{(z^k, \xi^k)\}_{k \geq 0}$ with $(z^k, \xi^k) = (x^{B\flr{k / B}}, \xi^k)$ is the corresponding auxiliary sequence, and $\frac{1}{K}\sum_{k=0}^{K-1}\Exp{\|\nabla f(x^k)\|^2} \le \varepsilon$ for all 
  $$
  K \geq \frac{4 B L \Delta}{\varepsilon} + \frac{8 \sigma^2 L \Delta}{\varepsilon^2}.
  $$
  with step size $\gamma = \min\{\frac{1}{2 B L}, \frac{\varepsilon}{4 \sigma^2 L}\}.$
  \label{thm:rennala}
\end{theorem}
% The following proof is detailed to provide clearer initial intuition about the framework.
\begin{proof}
  Clearly, $\{x^k\}_{k \geq 0}$ is a main branch and $\{(z^k, \xi^k)\}_{k \geq 0}$ is the corresponding sequence by the construction in \eqref{eq:dOBxW}. Moreover, $\xi^k$ is independent of $\{(x^{i+1}, z^{i+1}, \xi^i)\}_{i=0}^{k-1}$ in \eqref{eq:dOBxW} because $\{\xi^i\}$ are i.i.d. (Condition 1 is satisfied). Next, notice that
  \begin{align*}
  &\textnormal{repr}(z^0) = \textnormal{repr}(x^0) = \emptyset, \\
  &\textnormal{repr}(z^1) = \textnormal{repr}(x^0) = \emptyset \subseteq \textnormal{repr}(x^1), \\
  &\qquad\qquad \vdots \\
  &\textnormal{repr}(z^{B-1}) = \textnormal{repr}(x^0) = \emptyset \subseteq \textnormal{repr}(x^{B-1})
  \end{align*}
  because $z^k = x^0$ for all $k < B.$ Next, 
  \begin{align*}
    &\textnormal{repr}(z^B) = \textnormal{repr}(x^B), \\
    &\textnormal{repr}(z^{B+1}) = \textnormal{repr}(x^B) \subseteq \textnormal{repr}(x^{B+1}), \\
    &\quad\qquad\qquad \vdots \\
    &\textnormal{repr}(z^{2 B-1}) = \textnormal{repr}(x^B) \subseteq \textnormal{repr}(x^{2 B-1}),
  \end{align*}
  because $z^k = x^B$ for all $B \leq k < 2 B,$ where $\textnormal{repr}(x^B) \subseteq \textnormal{repr}(x^{B+1}), \dots, \textnormal{repr}(x^B) \subseteq \textnormal{repr}(x^{2 B - 1})$ due to \eqref{eq:dOBxW}. We can continue and show that $\textnormal{repr}(z^k) \subseteq \textnormal{repr}(x^k)$ for all $k \geq 0$ (Condition 2 is satisfied). It is left to notice that 
  \begin{align*}
    \sup_{k \geq 0} \textnormal{dist}(x^k, z^k) \leq B - 1,
  \end{align*}
  because 
  \begin{align*}
    \textnormal{dist}(x^0, z^0) &= 0, \\
    \textnormal{dist}(x^1, z^1) = \textnormal{dist}(x^1, x^0) &= 1, \\
    &\vdots \\
    \textnormal{dist}(x^{B-1}, z^{B-1}) = \textnormal{dist}(x^{B-1}, x^0) &= B - 1,  \\
    \textnormal{dist}(x^{B}, z^{B}) = \textnormal{dist}(x^{B}, x^{B}) &= 0, \\
    \textnormal{dist}(x^{B + 1}, z^{B + 1}) = \textnormal{dist}(x^{B + 1}, x^{B}) &= 1, \\
    &\vdots
  \end{align*}
  The maximum tree distance between $x^k$ and $z^k$ is $B - 1$. Thus, $R = B - 1$ in Condition 3.
\end{proof}

