\subsection{\algname{Local SGD}}
\label{sec:local_sgd}

The \algname{Local SGD} method is described in the following algorithm:
\begin{algorithm}[H]
  \caption{\algname{Local SGD}}
  \label{alg:local_sgd}
  \begin{algorithmic}[1]
  \REQUIRE Initial model $w^0$, step size $\gamma$, parameter $B$
  \FOR{$k = 0, 1, 2, \dots$}
      \STATE Broadcast $w^k$ to all workers
      \FOR{each worker $i \in [n]$ \textbf{in parallel}}
          \STATE Worker $i$ starts \texttt{LocalSGDWorker}($w^k, \gamma$) from Algorithm~\ref{alg:local_sgd_worker_function}
      \ENDFOR
      \STATE Wait for the moment when $\sum_{i=1}^{n} M_i = B$ \hfill ($\{M_i\}$ from \texttt{LocalSGDWorker}($w^k, \gamma$))
      \STATE Ask workers to stop\footnotemark running \texttt{LocalSGDWorker}($w^k, \gamma$)
      \STATE Aggregate $\gamma \sum_{i=1}^{n} \sum_{j=0}^{M_i - 1} \nabla f(z^{k,j}_i; \eta^{k,j}_i)$ from the workers  (e.g, via \texttt{AllReduce})
      \STATE Update $w^{k+1} = w^{k} - \gamma \sum_{i=1}^{n} \sum_{j=0}^{M_i - 1} \nabla f(z^{k,j}_i; \eta^{k,j}_i)$
  \ENDFOR
  \end{algorithmic}
\end{algorithm}

\newcommand{\footnotesametext}{Alternatively, allow the workers to finish computing their stochastic gradients without waiting for them (since \texttt{AllReduce} can be run in parallel), but discard these gradients in subsequent iterations, as they are no longer relevant. This approach may introduce a delay before the workers begin their next local steps. \\

Another option is to allow the workers to finish computing their stochastic gradients without waiting for them, and send these gradients in the next iteration. If some gradients are still not computed by then due to delays, simply discard them.}
% We leave it as future work.}
% One can show that this strategy does not degrade the theoretical convergence rate (up to constant factors). We leave it as future work for simplicity of presentation because it is a little bit technical without deep insights.}

\footnotetext{\footnotesametext \label{foot:local_sgd_stop}}
% \footnotetext{Alternatively, allow the workers to finish computing their stochastic gradients without waiting for them—since \texttt{AllReduce} can run in parallel—and send these gradients in the next iteration. If some gradients are still not computed by then due to delays, simply discard them. \label{foot:local_sgd_stop}}

\begin{algorithm}[H]
  \caption{\texttt{LocalSGDWorker}($w, \gamma$) in worker $i$ at round $k$}
  \label{alg:local_sgd_worker_function}
  \begin{algorithmic}[1]
    \STATE $z^{k,0}_i = w$
    \STATE $M_i \gets 0$
    \WHILE{True}
        \STATE $z^{k,M_i + 1}_i = z^{k,M_i}_i - \gamma \nabla f(z^{k,M_i}_i; \eta^{k,M_i}_i), \quad \eta^{k,M_i}_i \sim \mathcal{D}_{\xi}$
        \STATE $M_i = M_i + 1$
    \ENDWHILE
  \end{algorithmic}
\end{algorithm}

One key change compared to the previous work is that individual local steps $M_i$ are not predefined. Moreover, the server tracks the sum $\sum_{i=1}^{n} M_i$ and waits for the moment $\sum_{i=1}^{n} M_i = B$ before collecting the locally calculated gradients. With a proper choice of $B,$ we will prove the optimal computational time complexity of the method in Section~\ref{sec:proof_compt}.

The corresponding computation tree of \algname{Local SGD} can be constructed in the following way. Define $N_k \eqdef k \times B$ and take $k = 0.$ Then
\begin{eqnarray}
  \begin{aligned}
  &z^{k,1}_i = z^{k,0}_i - \gamma \nabla f(x^{N_k}; \eta^{k,0}_i), \\
  &z^{k,2}_i = z^{k,1}_i - \gamma \nabla f(z^{k,1}_i; \eta^{k,1}_i), \\
  &\qquad \vdots \\
  &z^{k,M_i}_i = z^{k,M_i - 1}_i - \gamma \nabla f(z^{k,M_i - 1}_i; \eta^{k,M_i - 1}_i),
  \label{eq:pbHgXapdjZGUQs}
\end{aligned}
\end{eqnarray}
for all $i \in [n],$ and
\begin{eqnarray}
\begin{aligned}
  x^{N_k + 1}   &= x^{N_k} - \gamma \nabla f(z^{k, 0}_1; \eta^{k, 0}_1), \\
  &\vdots\\
  x^{N_k + M_1} &= x^{N_k + M_1 - 1} - \gamma \nabla f(z^{k, M_1 - 1}_1; \eta^{k, M_1 - 1}_1), \\
  x^{N_k + M_1+1} &= x^{N_k + M_1} - \gamma \nabla f(z^{k, 0}_2; \eta^{k, 0}_2), \\
  &\vdots\\
  x^{N_k + M_1 + M_2} &= x^{N_k + M_1 + M_2 - 1} - \gamma \nabla f(z^{k, M_2 - 1}_2; \eta^{k, M_2 - 1}_2), \\
  &\vdots\\
  x^{N_{k + 1}} &= x^{N_k + \sum_{i=1}^{n} M_i - 1} - \gamma \nabla f(z^{k, M_n - 1}_{n}; \eta^{k, M_n - 1}_{n}).
  \label{eq:yapgNwHcHepGaY}
\end{aligned}
\end{eqnarray}
Repeat the previous steps with $k = k + 1$ starting at $x^{N_{k + 1}} = x^{N_k + B}.$ See illustration in Figure~\ref{fig:local_sgd_graph}. One can easily show that $w^{1} = x^{B}, w^{2} = x^{2 B}, \dots, w^{k} = x^{k B}, \dots, $ where $w^{k}$ is the sequence from Algorithm~\ref{alg:local_sgd}.

\begin{theorem}
  Let Assumptions~\ref{ass:lipschitz_constant}, \ref{ass:lower_bound}, and \ref{ass:stochastic_variance_bounded} hold. Consider the computation tree (\eqref{eq:pbHgXapdjZGUQs} and \eqref{eq:yapgNwHcHepGaY}) of \algname{Local SGD}, then $\{x^k\}_{k \geq 0}$ is a main branch
  % , $\{(z^k, \xi^k)\}_{k \geq 0}$ with $$(z^k, \xi^k) = (x^{B\flr{k / B}}, \xi^k)$$ is the corresponding auxiliary sequence, 
  and $\frac{1}{K}\sum_{k=0}^{K-1}\Exp{\|\nabla f(x^k)\|^2} \le \varepsilon$ for all 
  $$
  K \geq \frac{4 B L \Delta}{\varepsilon} + \frac{8 \sigma^2 L \Delta}{\varepsilon^2}.
  $$
  with step size $\gamma = \min\{\frac{1}{2 B L}, \frac{\varepsilon}{4 \sigma^2 L}\}.$
  \label{thm:local_sgd}
\end{theorem}

Although the proof may seem technical due to the heavy notation in \eqref{eq:yapgNwHcHepGaY}, it is actually straightforward when you refer to Figure~\ref{fig:local_sgd_graph}. This figure clearly shows that all conditions of Theorem~\ref{thm:main} are satisfied with $R = B - 1$ because $\sum_{i=1}^n M_i = B$ in every global iteration. The condition $\sum_{i=1}^n M_i = B$ helps us to insure that the maximum tree distance $\sup_{k \geq 0} \textnormal{dist}(x^k, z^k) \leq B - 1.$

\begin{proof}
  Clearly, $\{x^k\}_{k \geq 0}$ is a main branch by Definition~\ref{def:branch}. The corresponding auxiliary sequence can be inferred from \eqref{eq:yapgNwHcHepGaY}: $(z^0, \xi^0) = (z^{0, 0}_1, \eta^{0, 0}_1), \dots, (z^{M_1}, \xi^{M_1}) = (z^{0, M_1}_1, \eta^{0, M_1}_1),$ and etc. Condition 1 is satisfied because $\{\eta^{k, j}_{i}\}$ are i.i.d., and by the construction \eqref{eq:yapgNwHcHepGaY}. Condition 2 of Theorem~\ref{thm:main} holds because the same stochastic gradients used for computing $z^{k}$ are also used for $x^{k}$, as shown in Figure~\ref{fig:local_sgd_graph}. This can be formally verified using \eqref{eq:yapgNwHcHepGaY} and \eqref{eq:pbHgXapdjZGUQs}.
  It is left to notice that 
  \begin{align*}
    \sup_{k \geq 0} \textnormal{dist}(x^k, z^k) \leq B - 1
  \end{align*}
  because the maximum number of edges to the common closest ancestor can not exit $B - 1$.
\end{proof}


% Condition 2 of Theorem~\ref{thm:main} is satisfied because the stochastic gradients used to compute $z^{j}_i$ are also used to compute $x^{k},$ where $\nabla f(z^{j}_i; \xi^{j}_i)$ is applied to compute $x^{k+1}.$ For any such $z^{j}_i$ and $x^{k},$ $\textnormal{dist}(x^{k}, z^{j}_i) \leq \sum_{i=1}^{n} M_i - 1$ (see Figure~\ref{fig:local_sgd_graph}). Thus, the \emph{iteration rate} is $\cO\left(\nicefrac{(\sum_{i=1}^{n} M_i) L \Delta}{\varepsilon} + \nicefrac{\sigma^2 L \Delta}{\varepsilon^2}\right).$

