\subsection{\algname{Ringmaster ASGD}}
\label{sec:ringmaster_asgd}

\begin{algorithm}[H]
  \caption{\algname{Ringmaster ASGD} \citep{maranjyan2025ringmaster}}
  \label{alg:ringmasternew}
  \begin{algorithmic}[1]
      \STATE \textbf{Input:} point $w^0 \in \R^d$, stepsize $\gamma > 0,$ delay threshold $G \in \N$
      \STATE Set $k = 0$
      \STATE Workers start computing stochastic gradients at $w^0$
      \WHILE{True}
          \STATE Gradient $\nabla f(w^{k-\delta^k}; \eta^{k-\delta^k}_{i})$ arrives from worker $i$
          \IF{$\delta^k < G$}
          \STATE Update: $w^{k+1} = w^{k} - \gamma \nabla f(w^{k-\delta^k}; \eta^{k-\delta^k}_{i})$
          \STATE Worker $i$ begins calculating at $w^{k+1}$ \hfill ($\{\eta^{k}_{i}\}$ are i.i.d.)
          \STATE Update the iteration number $k = k + 1$
          \ELSE
          \STATE Ignore the outdated gradient $\nabla f(w^{k-\delta^k}; \eta^{k-\delta^k}_{i})$
          \STATE Worker $i$ begins calculating at $w^{k}$
          \ENDIF
      \ENDWHILE
  \end{algorithmic}
\end{algorithm}

In this method, a main branch can be defined as 
\begin{align}
  x^k = w^k
  \label{eq:JYByrgqAiCTpxi}
\end{align}
and the auxiliary sequence is defined as $(z^k, \xi^k) = (x^{k - \delta^k}, \eta^{k - \delta^k}_{i})$ for all $k \geq 0.$

\begin{figure}[h]
  \centering
  \includegraphics[page=12,width=0.5\textwidth]{./graphs/graphs_new.pdf}
  \caption{The computation tree of \algname{Ringmaster ASGD}}
  \label{fig:async_sgd_graph}
\end{figure}

\begin{theorem}
  \label{thm:ringmaster_asgd}
  Let Assumptions~\ref{ass:lipschitz_constant}, \ref{ass:lower_bound}, and \ref{ass:stochastic_variance_bounded} hold. Consider the computation tree of \algname{Ringmaster ASGD}, then $\{x^k\}_{k \geq 0},$ defined in \eqref{eq:JYByrgqAiCTpxi}, is a main branch
  and $\frac{1}{K}\sum_{k=0}^{K-1}\Exp{\|\nabla f(x^k)\|^2} \le \varepsilon$ for all 
  $$
  K \geq \frac{4 G L \Delta}{\varepsilon} + \frac{8 \sigma^2 L \Delta}{\varepsilon^2}.
  $$
  with step size $\gamma = \min\{\frac{1}{2 G L}, \frac{\varepsilon}{4 \sigma^2 L}\}.$
\end{theorem}

\begin{proof}
  Condition 1 is satisfied because $\{\eta^{k-\delta^k}_{i}\}$ are i.i.d., $x^{k} = w^k$ and $z^k = x^{k-\delta^k}$ do not depend on $\xi^k = \eta^{k-\delta^k}_{i}.$ Condition 2 is satisfied because $\textnormal{repr}(z^{k}) = \textnormal{repr}(w^{k-\delta^k}) \subseteq \textnormal{repr}(w^{k}) = \textnormal{repr}(x^{k}).$ Condition 3 is satisfied with $R = G - 1$ because
  \begin{align*}
    \textnormal{dist}(x^k, z^k) = \textnormal{dist}(x^{k}, x^{k-\delta^k}) = \delta^k \leq G - 1,
  \end{align*}
  where the second equality due to the number of edges between $x^{k}$ and $x^{k-\delta^k}$ and the last inequality due to the fact that $\delta^k$ is bounded by $B$ in Algorithm~\ref{alg:ringmasternew}.
\end{proof}

