\subsection{\algname{Cycle SGD}}
\label{sec:circular_sgd}

We now present a new method, called \algname{Cycle SGD}:

\begin{algorithm}[H]
  \caption{\algname{Cycle SGD}}
  \label{alg:circular_local_sgd}
  \begin{algorithmic}[1]
  \REQUIRE Initial model $w^0$, step size $\gamma$, group size $s$
  \STATE Partition workers into groups of size $s$: 
      $$G_1 = \{1, \dots, s\}, G_2 = \{s + 1, \dots, 2 s\}, \dots, G_{\lceil n/s \rceil} = \{(\lceil n/s \rceil - 1) s + 1, \dots, n\}$$ 
      in a circular manner.
  \STATE Broadcast $w^{0}$ to all workers and assign the local variables $z^0_i = w^{0}$ and $M_i = 0$ for all $i \in [n]$
  \WHILE{True}
      \FOR{group index $g = 1$ to $\lceil n/s \rceil$}
          \FOR{each worker $i \in [n]$ \textbf{in parallel}}
            \STATE $z_i^{M_i + 1} = z_i^{M_i} - \gamma \nabla f(z_i^{M_i}; \eta_i^{M_i}), \quad \eta_i^{M_i} \sim \mathcal{D}_{\xi}$
            \STATE $M_i = M_i + 1$
          \ENDFOR
          \STATE Aggregate $\gamma \sum_{i \in G_g} \sum_{j=1}^{M_i} \nabla f(z^{j}_i; \eta^{j}_i)$ from the workers of group $G_g$ only
          \STATE Server aggregates and updates the model:
          $$
              w^{r+1} = w^r - \gamma \sum_{i \in G_g} \sum_{j=0}^{M_i - 1} \nabla f(z^{j}_i; \eta^{j}_i)
          $$
          \STATE Broadcast $w^{r + 1}$ to all workers of group $g$ and assign the local variables $z^0_i = w^{r + 1}$ and $M_i = 0$ for all $i \in G_g$
          \STATE $r = r + 1$
      \ENDFOR
  \ENDWHILE
  \end{algorithmic}
\end{algorithm}

This method operates similarly to \algname{Local SGD}, with workers performing local steps. However, a key difference is that only $s$ workers synchronize at each step, rather than all $n$ workers. This strategy can be advantageous in scenarios where reducing peak bandwidth is desirable. A visualization of the corresponding computation tree is in Figure~\ref{fig:circular_local_sgd_graph}. For this algorithm, the first $\sum_{i=1}^{n} M_i$ nodes of the main branch can be defined as
\begin{equation}
\begin{aligned}
  \label{eq:whoDleMteaoI}
  x^{1} &= x^{0} - \gamma \nabla f(z^{0}_1; \eta^{0}_1), \\
  &\vdots\\
  x^{M_1} &= x^{M_1 - 1} - \gamma \nabla f(z^{M_1 - 1}_1; \eta^{M_1 - 1}_1), \\
  &\vdots\\
  x^{\sum_{i=1}^{s-1} M_i + 1} &= x^{\sum_{i=1}^{s-1} M_i} - \gamma \nabla f(z^{0}_{s}; \eta^{0}_{s}), \\
  &\vdots \\
  x^{\sum_{i=1}^{s} M_i} &= x^{\sum_{i=1}^{s} M_i - 1} - \gamma \nabla f(z^{M_s - 1}_s; \eta^{M_s - 1}_s), \\
  &\vdots \\
\end{aligned}
\end{equation}
Notice that $x^{\sum_{i=1}^{s} M_i} \equiv w^{1},$ where we capture and unroll all stochastic gradients from the first group. The next nodes of the main branch can be defined in a similar way going through all groups circularly.

\begin{figure}[h]
  \centering
  \includegraphics[page=14,width=0.5\textwidth]{./graphs/graphs_new.pdf}
  \caption{An example of \algname{Cycle SGD} computation tree.}
  \label{fig:circular_local_sgd_graph}
\end{figure}

\begin{theorem}
  Let Assumptions~\ref{ass:lipschitz_constant}, \ref{ass:lower_bound}, and \ref{ass:stochastic_variance_bounded} hold. Consider the computation tree of \algname{Cycle SGD} (Alg.~\ref{alg:circular_local_sgd}), then $\{x^k\}_{k \geq 0},$ defined in \eqref{eq:whoDleMteaoI}, is a main branch
  and $\frac{1}{K}\sum_{k=0}^{K-1}\Exp{\|\nabla f(x^k)\|^2} \le \varepsilon$ for all 
  $$
  K \geq \frac{8 n^2 L \Delta}{s \varepsilon} + \frac{8 \sigma^2 L \Delta}{\varepsilon^2}.
  $$
  with step size $\gamma = \min\{\frac{s}{4 n^2 L}, \frac{\varepsilon}{4 \sigma^2 L}\}.$
  \label{thm:circular_local_sgd}
\end{theorem}

\begin{proof}
  Once again, the proof is geometric. As an example, consider Figure~\ref{fig:circular_local_sgd_graph} together with Algorithm~\ref{alg:circular_local_sgd}. One can easily show that Conditions 1 and 2 are satisfied similarly to the proof of Theorem~\ref{alg:local_sgd}. However, the maximum tree distance is different since we synchronize the workers in a circular manner.

  First, the number of local steps $M_i \leq \left\lceil\frac{n}{s}\right\rceil \leq \frac{2n}{s}$ because each worker computes one stochastic gradient in the inner loop and synchronizes every $\left\lceil\frac{n}{s}\right\rceil$ loops.

  Next, the maximum tree distance between a point $x^{k}$ on the main branch and the corresponding point of the auxiliary sequence $z^{k}$ is at most $\frac{2n^2}{s}$. Let us explain this step. Consider any $x^{k}$ and $z^{k}$, and their closest common ancestor $w^k$ (in Figure~\ref{fig:circular_local_sgd_graph}, for instance, take $x^{5}$, $z^{2,2}_2$, and $x^{3}$ accordingly).

  The number of edges from $z^{k}$ to $w^k$ never exceeds $\frac{2n}{s}$ due to the bound on the number of local steps. The number of edges from $x^{k}$ to $w^k$ never exceeds $\frac{2n^2}{s}$ because, while one worker performs local steps, other workers can grow the main branch by at most $\left\lceil\frac{n}{s}\right\rceil \times (n - 1) \leq \frac{2n (n - 1)}{s}$ points before the worker that computed $z^k$ is synchronized\footnote{For instance, see Figure~\ref{fig:circular_local_sgd_graph}, where, before the algorithm applies $\nabla f(z^{2,1}_{2};\xi^{2,1}_{2})$ from the second worker, the main branch grows by two edges, from $x^{3}$ to $x^{5}$, due to gradients computed by the first worker.}.

  Thus, we can take $R = \frac{2n^2}{s}$ in Condition 3 of Theorem~\ref{thm:main}.
\end{proof}

% \STATE $z^0_i = w$
