\subsection{\algname{Async-Local SGD}}
\label{sec:async_plus_local}
The following algorithm is a mixture of \algname{Asynchronous SGD} and \algname{Local SGD}, which we formalize in the following way.

\begin{algorithm}[H]
  \caption{\algname{Async-Local SGD}}
  \label{alg:async_plus_local}
  \begin{algorithmic}[1]
      \STATE \textbf{Input:} point $x^0 \in \R^d$, stepsize $\gamma > 0,$ delay threshold $B \in \N,$ number of local steps $M$
      \STATE Set $k = 0$
      \STATE Workers start running local steps at $w^0$ with Alg.~\ref{alg:local_sgd_worker_function_mix} for $M$ steps
      \WHILE{True}
          \STATE Sum $\gamma \sum_{p = 0}^{M - 1} \nabla f(z^{p}_{i_k}; \eta^{p}_{i_k})$ arrives from some worker $i_k$
          \STATE Find the tree distance $\delta^k = \textnormal{dist}(w^{k}, z^{0}_{i_k})$ \\ (delay $\delta^k$ of $w^{k - \delta^k},$ at which point worker $i_k$ started local steps)
        \IF{$\delta^k < B$}
          \STATE Update: $w^{k+1} = w^{k} - \gamma \sum_{p = 0}^{M - 1} \nabla f(z^{p}_{i_k}; \eta^{p}_{i_k})$
          \STATE Worker $i$ starts running local steps at $w^{k+1}$ with Alg.~\ref{alg:local_sgd_worker_function_mix} for $M$ steps
          \STATE Update the iteration number $k = k + 1$
          \ELSE
          \STATE Ignore the outdated sum $\gamma \sum_{p = 0}^{M - 1} \nabla f(z^{p}_{i_k}; \eta^{p}_{i_k})$
          \STATE Worker $i$ starts running local steps at $w^{k}$ with Alg.~\ref{alg:local_sgd_worker_function_mix} for $M$ steps
          \ENDIF
      \ENDWHILE
  \end{algorithmic}
\end{algorithm}

\begin{algorithm}[H]
  \caption{\texttt{LocalSGDWorker}($w, \gamma, M$) in worker $i$}
  \label{alg:local_sgd_worker_function_mix}
  \begin{algorithmic}[1]
    \STATE $z^{0}_i = w$
    \FOR{$p = 0, \dots M - 1$}
        \STATE $z^{p + 1}_i = z^{p}_i - \gamma \nabla f(z^{p}_i; \eta^{p}_i), \quad \eta^{p}_i \sim \mathcal{D}_{\xi}$
    \ENDFOR
    \STATE Send to the server $\gamma \sum_{p = 0}^{M - 1} \nabla f(z^{p}_i; \eta^{p}_i)$
  \end{algorithmic}
\end{algorithm}

If $M = 1,$ then this method reduces to \algname{Ringmaster ASGD} (Alg.~\ref{alg:ringmasternew}). Taking $M > 1,$ we can improve the time complexity of \algname{Ringmaster ASGD} by decreasing the number of times when workers synchronize with the server. For this method, it is natural to take a main branch as
\begin{equation}
\begin{aligned}
  x^{1} &= x^{0} - \gamma \nabla f(z^{0}_{i_1}; \eta^{0}_{i_1}), \\
  &\vdots \\
  x^{M} &= x^{M - 1} - \gamma \nabla f(z^{M - 1}_{i_1}; \eta^{M - 1}_{i_1}),\\
  &\vdots \\
  x^{M (k - 1) + 1} &= x^{M (k - 1)} - \gamma \nabla f(z^{0}_{i_k}; \eta^{0}_{i_k}), \\
  &\vdots, \\
  x^{M k} &= x^{M k - 1} - \gamma \nabla f(z^{M - 1}_{i_k}; \eta^{M - 1}_{i_k}), \\
  &\vdots
  \label{eq:kfHzyNb}
\end{aligned}
\end{equation}
and so on. Notice that $x^0 \equiv w^0, x^{M} \equiv w^1,$ etc.

\begin{theorem}
  Let Assumptions~\ref{ass:lipschitz_constant}, \ref{ass:lower_bound}, and \ref{ass:stochastic_variance_bounded} hold. Consider the computation tree of \algname{Async-Local SGD} (Alg.~\ref{alg:async_plus_local}), then $\{x^k\}_{k \geq 0},$ defined in \eqref{eq:kfHzyNb}, is a main branch
  and $\frac{1}{K}\sum_{k=0}^{K-1}\Exp{\|\nabla f(x^k)\|^2} \le \varepsilon$ for all 
  $$
  K \geq \frac{4 (B + M - 1) L \Delta}{\varepsilon} + \frac{8 \sigma^2 L \Delta}{\varepsilon^2}.
  $$
  with step size $\gamma = \min\{\frac{1}{4 (B + M - 1) L}, \frac{\varepsilon}{4 \sigma^2 L}\}.$
  \label{thm:async_plus_local}
\end{theorem}

\begin{proof}
  Similar to the previous proofs, Condition 1 is satisfied for the main branch $\{x^k\}_{k \geq 0}$ because all random variables $\{\eta^{i}_{j}\}$ in \eqref{eq:kfHzyNb} are i.i.d., and $x^{0}$ and $z^{0}_{i_1}$ do not depend on $\eta^{0}_{i_1}.$ Points $x^{M - 1}$ and $z^{M - 1}_{i_1}$ do not depend on $\eta^{M - 1}_{i_1},$ and so on. Conditions 2 is satisfied because all stochastic gradients used to compute $z^{p}_{i_k}$ are also used to compute the corresponding point on the main branch for all $p \in \{0, \dots, M - 1\}$ and $k \geq 0$ (see Figure~\ref{fig:async_plus_local}). Condition 3 is satisfied with $R = B - 1 + M - 1 = B + M - 2$ due to the inequality $\delta^k = \textnormal{dist}(w^{k}, z^{0}_{i_k}) < B$ in Algorithm~\ref{alg:async_plus_local} and the fact every worker calculates $M$ stochastic gradients, which ensures that the tree distance between $z^{0}_{i_k}$ and the corresponding point from the main brain branch is at most $B - 1,$ the tree distance between $z^{1}_{i_k}$ and the corresponding point from the main brain branch is at most $B - 2,$ $\dots,$ the tree distance between $z^{M - 1}_{i_k}$ and the corresponding point from the main brain branch is at most $B + M - 2.$
\end{proof}

\subsection{\algname{Async-Batch SGD}}
\label{sec:async_batch}
This method does the same steps as \algname{Async-Local SGD} with the only difference that the workers calculate mini-batches instead of local steps:
\begin{algorithm}[H]
\caption{\texttt{BatchSGDWorker}($w, \gamma, M$) in worker $i$}
\label{alg:local_sgd_worker_function_mix_batch}
\begin{algorithmic}[1]
    \STATE $z^{0}_i = w$
    \FOR{$p = 0, \dots M - 1$}
        \STATE Calculate $\nabla f(z^{p}_i; \eta^{p}_i), \quad \eta^{p}_i \sim \mathcal{D}_{\xi}$
        \STATE $z^{p + 1}_i = z^{p}_i$
    \ENDFOR
    \STATE Send to the server $\gamma \sum_{p = 0}^{M - 1} \nabla f(z^{p}_i; \eta^{p}_i)$
\end{algorithmic}
\end{algorithm}

One can easily show that these methods share the same theoretical guarantees (Sections~\ref{sec:async_plus_local}, \ref{sec:proof_compt}, and \ref{sec:proof_communication}) as \algname{Async-Local SGD}.

