\subsection{\algname{Local-Async SGD}}
\label{sec:local_plus_async}
One way to interpret the following algorithm is that the workers are partitioned into groups, with each group running \algname{Asynchronous SGD}. Then, at certain points, all workers synchronize, and start running \algname{Asynchronous SGD} at a new point. One of the important novelties here is the condition $\sum_{g=1}^{s} m_g = B,$ which, with a proper $B,$ leads to the optimal computational time complexity (Section~\ref{sec:proof_compt}).

\begin{algorithm}[H]
  \caption{\algname{Local-Async SGD}}
  \label{alg:grouped_async_local_sgd}
  \begin{algorithmic}[1]
  \REQUIRE Initial model $w^0$, step size $\gamma$, parameter $B,$ group partitions $G_1, \dots, G_s$
  \FOR{$k = 0, 1, 2, \dots$}
      \STATE Broadcast $w^k$ to all groups
      \FOR{each worker $g \in [s]$ \textbf{in parallel}}
          \STATE Group $g$ starts AsynchronousSGDGroup($w^k, \gamma$) from Algorithm~\ref{alg:local_sgd_worker_function_mix_sgd}
      \ENDFOR
      \STATE Wait for the moment when $\sum_{g=1}^{s} m_g = B$ \hfill ($\{m_g\}$ from AsynchronousSGDGroup($w^k, \gamma$))
      \STATE Ask the groups to stop\footnotemark running AsynchronousSGDGroup($w^k, \gamma$)
      \STATE Aggregate $\gamma \sum_{g=1}^{s} \sum_{j=0}^{m_g - 1} \nabla f(v^{j-\delta^{j}}_g; \eta^{j}_{g})$ from the groups \hfill ($\{\eta^{j}_g\}$ are i.i.d.)
      \STATE Update $w^{k+1} = w^{k} - \gamma \sum_{g=1}^{s} \sum_{j=0}^{m_g - 1} \nabla f(v^{j-\delta^{j}}_g; \eta^{j}_{g})$
  \ENDFOR
  \end{algorithmic}
\end{algorithm}

% \footnotetext{Alternatively, allow the workers to finish computing their stochastic gradients without waiting for them (\texttt{AllReduce} can be run in parallel), but discard these gradients in subsequent iterations, as they are no longer relevant. This approach may introduce a delay before the workers begin their next local steps.}
\footnotetext{\footnotesametext}
% \footnotetext{Alternatively, allow the workers to finish computing their stochastic gradients without waiting for them—since \texttt{AllReduce} can run in parallel—and send these gradients in the next iteration. If some gradients are still not computed by then due to delays, simply discard them.}

\begin{algorithm}[H]
  \caption{AsynchronousSGDGroup($w, \gamma$) in group $g$}
  \label{alg:local_sgd_worker_function_mix_sgd}
  \begin{algorithmic}
      \STATE \textbf{Input:} point $v^0_g \in \R^d$, stepsize $\gamma > 0$
      \STATE Set $m_g = 0$
      \STATE Workers from group $g$ start computing stochastic gradients at $v^0_g$
      \WHILE{True}
          \STATE Gradient $\nabla f(v^{m_g-\delta^{m_g}}_g; \eta^{m_g}_{g})$ arrives from worker $i$ with delay $\delta^{m_g}$
          \STATE Update: $v^{m_g + 1}_g = v^{m_g}_g - \gamma \nabla f(v^{m_g-\delta^{m_g}}_g; \eta^{m_g}_{g})$
          \STATE Worker $i$ begins calculating stochastic gradient at $v^{m_g + 1}_g$
          \STATE Update the iteration number $m_g = m_g + 1$
      \ENDWHILE
  \end{algorithmic}
\end{algorithm}

For this method, it is natural to take a main branch of the computation tree as
\begin{equation}
\begin{aligned}
  \label{eq:OjRVuNSYZjFplZrfxBaN}
  x^{1} &= x^{0} - \gamma \nabla f(v^{0-\delta^{0}}_1; \eta^{0}_{1}), \\
  &\vdots \\
  x^{m_1} &= x^{m_1 - 1} - \gamma \nabla f(v^{m_1 - 1 -\delta^{m_1 - 1}}_1; \eta^{m_1 - 1}_{1}),\\
  &\vdots \\
  x^{\sum_{g=1}^{s - 1} m_i + 1} &= x^{\sum_{g=1}^{s - 1} m_i} - \gamma \nabla f(v^{0-\delta^{0}}_s; \eta^{0}_{s}), \\
  &\vdots, \\
  x^{\sum_{g=1}^{s} m_i} &= x^{\sum_{g=1}^{s} m_i - 1} - \gamma \nabla f(v^{m_s - 1 -\delta^{m_s - 1}}_s; \eta^{m_s - 1}_{s}) \\
  &\vdots,
\end{aligned}
\end{equation}
where one can see that $x^{\sum_{g=1}^{s} m_i} \equiv x^{B} \equiv w^1,$ and $\{v^{j}_{g}\}$ is defined in Algorithm~\ref{alg:local_sgd_worker_function_mix_sgd}.

\begin{figure}[H]
  \centering
  \includegraphics[page=16,width=0.8\textwidth]{./graphs/graphs_new.pdf}
  \caption{An example of a \algname{Local-Async SGD} computation tree with two groups and $B = 5$. One group performs $m_1 = 3$ steps of \algname{Asynchronous SGD}, while the other performs $m_2 = 2$ steps. Note that the maximum tree distance is $\textnormal{dist}(x^4, v^{1 - \delta^1}_1)$ when applying $\nabla f(v^{1 - \delta^1}_1; \eta^1_1)$ to $x^4$, and it equals $B - 1 = m_1 + m_2 - 1 = 4$. Then, the groups synchronize and continue from $x^5.$}
  \label{fig:local_sgd_worker_function_mix_sgd}
\end{figure}

\begin{theorem}
  Let Assumptions~\ref{ass:lipschitz_constant}, \ref{ass:lower_bound}, and \ref{ass:stochastic_variance_bounded} hold. Consider the computation tree of \algname{Local-Async SGD} (Alg.~\ref{alg:grouped_async_local_sgd}), then $\{x^k\}_{k \geq 0},$ defined in \eqref{eq:OjRVuNSYZjFplZrfxBaN}, is a main branch
  and $\frac{1}{K}\sum_{k=0}^{K-1}\Exp{\|\nabla f(x^k)\|^2} \le \varepsilon$ for all 
  $$
  K \geq \frac{4 B L \Delta}{\varepsilon} + \frac{8 \sigma^2 L \Delta}{\varepsilon^2}.
  $$
  with step size $\gamma = \min\{\frac{1}{4 B L}, \frac{\varepsilon}{4 \sigma^2 L}\}.$
  \label{thm:grouped_async_local_sgd}
\end{theorem}

\begin{proof}
  The proof closely follows that of Theorem~\ref{thm:local_sgd}, with the only difference being that the \emph{auxiliary branches} in Algorithm~\ref{alg:local_sgd_worker_function_mix_sgd} are constructed using asynchronous steps rather than local steps (compare Figure~\ref{fig:local_sgd_graph} and Figure~\ref{fig:local_sgd_worker_function_mix_sgd}). As in Theorem~\ref{thm:local_sgd}, the condition $\sum_{g=1}^{s} m_g = B$ ensures that $\sup_{k \geq 0} \textnormal{dist}(x^k, z^k) \leq B - 1.$
\end{proof}

