\section{Computational Time Complexities of Algorithms under $h_i$-Fixed Computation Model}
\label{sec:proof_compt}

To compare methods, we consider the \emph{$h_i$-fixed computation model} \citep{mishchenko2022asynchronous}.
In this model, it is assumed that
\begin{equation}
\begin{aligned}
    \text{worker } i \text{ takes no more than } h_i \text{ seconds} \text{ to compute a single stochastic gradient}
    \label{eq:worker-time}
\end{aligned}
\end{equation}
and 
\begin{equation}
    \label{eq:sorted_t_i}
    0<h_1\le h_2 \le \cdots \le h_n,
\end{equation}
without loss of generality.

Note that it is possible to consider the \emph{universal computation model} \citep{tyurin2024tight} and capture virtually all possible computation behaviors of the workers. While the \emph{$h_i$-fixed computation model} may seem more restrictive, it turns out that all optimal methods \citep{maranjyan2025ringmaster} in the \emph{universal computation model} are also optimal in the \emph{$h_i$-fixed computation model}. Thus, for simplicity, we stick to the \emph{$h_i$-fixed computation model}.


\subsection{\algname{Rennala SGD}}

\begin{theorem}[\algname{Rennala SGD}]
  Consider Theorem~\ref{thm:rennala} and its conditions. Under the $h_i$-fixed computation model \eqref{eq:worker-time}, the computational time complexity of \algname{Rennala SGD} (Alg.~\ref{alg:rennala}) is
  \begin{align} 
    \cO\left(\min\limits_{m \in [n]} \left[\left(\frac{1}{m} \sum\limits_{i=1}^{m} \frac{1}{h_i}\right)^{-1} \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{m \varepsilon^2}\right)\right]\right) 
    \label{eq:MFvzCXtfgWSefbzZ}
  \end{align}
  with $B = \max\left\{\left\lceil\frac{\sigma^2}{\varepsilon}\right\rceil, 1\right\}.$
  \label{thm:rennala_computation}
\end{theorem}

We start with the following lemma.

\begin{lemma}
  Let us define
  \begin{align}
    \label{eq:batch_time}
    T_{\textnormal{R}}(B) \eqdef 2 \min_{m\in[n]} \left[\left(\sum_{i=1}^m \frac{1}{h_i}\right)^{-1} (B + m)\right]
  \end{align}
  Under the $h_i$-fixed computation model \eqref{eq:worker-time}, the time required to calculate $x^{1}, \dots, x^{B}$ of the main branch is at most $T_{\textnormal{R}}(B)$ seconds, the time required to calculate $x^{B + 1}, \dots, x^{2B}$ is at most $T_{\textnormal{R}}(B)$ seconds, and so on.
  \label{lemma:rennala}
\end{lemma}

\begin{proof}
  The idea of \algname{Rennala SGD} (Alg.~\ref{alg:rennala}) is pretty simple. Notice that all workers calculate stochastic gradients at the same point in parallel until the server collects a batch of size $B$ (condition $\delta = 0$ ensures that). Since they work in parallel, under the fixed computational model, after $t$ seconds the workers will calculate
  \begin{align}
    \sum_{i = 1}^n \max\left\{\flr{\frac{t}{h_i}} - 1, 0\right\}
    \label{eq:KmmgS}
  \end{align}
  stochastic gradients because $\flr{\frac{t}{h_i}}$ is the number of stochastic gradients computed by worker $i$ in $t$ seconds. We subtract $1$ because at most one stochastic gradient be can be ignored due to the condition $\delta = 0$ in Alg.~\ref{alg:rennala}.

  Notice that 
  \begin{align*}
    T_{\textnormal{R}}(B) = 2 \left(\sum_{i=1}^{m^*} \frac{1}{h_i}\right)^{-1} (B + m^*)
  \end{align*}
  for some $m^* \in [n].$ Substituting it to \eqref{eq:KmmgS}, we get
  \begin{align*}
    \sum_{i = 1}^n \max\left\{\flr{\frac{T_{\textnormal{R}}(B)}{h_i}} - 1, 0\right\} 
    &\geq \sum_{i = 1}^{m^*} \max\left\{\flr{\frac{T_{\textnormal{R}}(B)}{h_i}} - 1, 0\right\} \geq \sum_{i = 1}^{m^*} \flr{\frac{T_{\textnormal{R}}(B)}{h_i}} - m^* \\
    &\geq \sum_{i = 1}^{m^*} \frac{T_{\textnormal{R}}(B)}{h_i} - 2 m^* = 2 (B + m^*) - 2 m^* \geq B.
  \end{align*}
  Thus, after $T_{\textnormal{R}}(B)$ seconds, the server collects $B$ stochastic gradients, which is equivalent to calculating $x^{1}, \dots, x^{B}$ of the main branch. The same argument can be applied to the next $B$ point of the main branch, and so on.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:rennala_computation}]
  Due to Theorem~\ref{thm:rennala}, we know that 
  $\frac{1}{K}\sum_{k=0}^{K-1}\Exp{\|\nabla f(x^k)\|^2} \le \varepsilon$ for
  $$
  K = \left\lceil\frac{4 B L \Delta}{\varepsilon} + \frac{8 \sigma^2 L \Delta}{\varepsilon^2}\right\rceil.
  $$
  From Lemma~\ref{lemma:rennala}, we know that the time required to calculate $x^{1}, \dots, x^{B}$ of the main branch is at most $T_{\textnormal{R}}(B)$ seconds, the time required to calculate $x^{B + 1}, \dots, x^{2B}$ is at most $T_{\textnormal{R}}(B)$ seconds, and so on. Thus, the total time to find an $\varepsilon$--stationary point is
  \begin{align*}
    \cO\left(T_{\textnormal{R}}(B) \times \frac{K}{B}\right) = \cO\left(T_{\textnormal{R}}(B) \times \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{B \varepsilon^2}\right)\right).
  \end{align*}
  Using the choice of $B,$
  \begin{align*}
    \cO\left(T_{\textnormal{R}}(B) \times \frac{K}{B}\right) 
    &= \cO\left(\min_{m\in[n]} \left[\left(\sum_{i=1}^m \frac{1}{h_i}\right)^{-1} (B + m)\right] \times \frac{L \Delta}{\varepsilon}\right) \\
    &= \cO\left(\min\limits_{m \in [n]} \left[\left(\frac{1}{m} \sum\limits_{i=1}^{m} \frac{1}{h_i}\right)^{-1} \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{m \varepsilon^2}\right)\right]\right).
  \end{align*}
\end{proof}

\subsection{\algname{Ringmaster ASGD}}

\begin{theorem}[\algname{Ringmaster ASGD}]
  Consider Theorem~\ref{thm:ringmaster_asgd} and its conditions. Under the $h_i$-fixed computation model \eqref{eq:worker-time}, the computational time complexity of \algname{Ringmaster ASGD} is
  \begin{align*} 
    \cO\left(\min\limits_{m \in [n]} \left[\left(\frac{1}{m} \sum\limits_{i=1}^{m} \frac{1}{h_i}\right)^{-1} \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{m \varepsilon^2}\right)\right]\right) 
  \end{align*}
  with $B = \max\left\{\left\lceil\frac{\sigma^2}{\varepsilon}\right\rceil, 1\right\}.$
  \label{thm:ringmaster_computation}
\end{theorem}

We use Lemma~4.1 from \citep{maranjyan2025ringmaster}.

\begin{lemma}(\citep{maranjyan2025ringmaster})
  \label{lem:time_R}
  Let the workers' computation times satisfy the \emph{$h_i$-fixed computation model} (\eqref{eq:worker-time} and \eqref{eq:sorted_t_i}).
  Let $B$ be the delay threshold of Alg.~\ref{alg:ringmasternew}.
  The time required to complete any $B$ consecutive iterate updates of Alg.~\ref{alg:ringmasternew} is at most
  \begin{equation}
      \label{eq:time_R}
      T_A(B) \eqdef 2 \min\limits_{m \in [n]} \left[\left(\frac{1}{m} \sum\limits_{i=1}^m \frac{1}{\tau_i}\right)^{-1} \left( 1 + \frac{R}{m} \right)\right].
  \end{equation}
\end{lemma}

\begin{corollary}
  In view of Lemma~\ref{lem:time_R}, Under the $h_i$-fixed computation model \eqref{eq:worker-time}, the time required to calculate $x^{1}, \dots, x^{B}$ of the main branch is at most $T_A(B)$ seconds, the time required to calculate $x^{B + 1}, \dots, x^{2B}$ is at most $T_A(B)$ seconds, and so on.
  \label{cor:time_R}
\end{corollary}

\begin{proof}[Proof of Theorem~\ref{thm:ringmaster_computation}]
  The proof of Theorem~\ref{thm:ringmaster_computation} is similar to the proof of Theorem~\ref{thm:rennala_computation}. From Corollary~\ref{cor:time_R}, we know that the time required to calculate $x^{1}, \dots, x^{B}$ of the main branch is at most $T_{\textnormal{A}}(B)$ seconds, the time required to calculate $x^{B + 1}, \dots, x^{2B}$ is at most $T_{\textnormal{A}}(B)$ seconds, and so on. Thus, the total time to find an $\varepsilon$--stationary point is
  \begin{align*}
    \cO\left(T_{\textnormal{A}}(B) \times \frac{K}{B}\right) = \cO\left(\min\limits_{m \in [n]} \left[\left(\frac{1}{m} \sum\limits_{i=1}^{m} \frac{1}{h_i}\right)^{-1} \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{m \varepsilon^2}\right)\right]\right).
  \end{align*}
\end{proof}

\subsection{\algname{Local SGD}}

\begin{theorem}[\algname{Local SGD}]
  Consider Theorem~\ref{thm:local_sgd} and its conditions. Under the $h_i$-fixed computation model \eqref{eq:worker-time}, the computational time complexity of \algname{Local SGD} (Alg.~\ref{alg:local_sgd}) is
  \begin{align*} 
    \cO\left(\min\limits_{m \in [n]} \left[\left(\frac{1}{m} \sum\limits_{i=1}^{m} \frac{1}{h_i}\right)^{-1} \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{m \varepsilon^2}\right)\right]\right) 
  \end{align*}
  with $B = \max\left\{\left\lceil\frac{\sigma^2}{\varepsilon}\right\rceil, 1\right\}.$
  \label{thm:local_computation}
\end{theorem}

\begin{lemma}
  Let us define
  \begin{align}
    T_{\textnormal{L}}(B) \eqdef 2 \min_{m\in[n]} \left[\left(\sum_{i=1}^m \frac{1}{h_i}\right)^{-1} (B + m)\right]
  \end{align}
  Under the $h_i$-fixed computation model \eqref{eq:worker-time}, the time required to calculate $x^{1}, \dots, x^{B}$ of the main branch is at most $T_{\textnormal{L}}(B)$ seconds, the time required to calculate $x^{B + 1}, \dots, x^{2B}$ is at most $T_{\textnormal{L}}(B)$ seconds, and so on.
  \label{lemma:local_sgd}
\end{lemma}

\begin{proof}
  The idea is the same as in Lemma~\ref{lemma:rennala}. All workers calculate stochastic gradients in parallel, with the only difference being that the points at which they compute the stochastic gradients differ due to the local steps. If the server can stop the workers, then after $t$ seconds it is possible to collect
\begin{align} \sum_{i=1}^{n} \flr{\frac{t}{h_i}} \label{eq:xpSINXLbaoIj} \end{align}
stochastic gradients. If it is infeasible to stop the calculations (see footnote~\ref{foot:local_sgd_stop}), then after $t$ seconds it is possible to collect
\begin{align} \sum_{i = 1}^n \max\left\{\flr{\frac{t}{h_i}} - 1, 0\right\}, \label{eq:xpSINXLbaoIj2} \end{align}
where we subtract $1$ because at most one stochastic gradient can be ignored if it is nonrelevant. Similarly to Lemma~\ref{lemma:rennala}, substituting $T_{\textnormal{L}}(B)$ into \eqref{eq:xpSINXLbaoIj} and \eqref{eq:xpSINXLbaoIj2}, one can show that $T_{\textnormal{L}}(B)$ is sufficient to collect $B = \sum_{i=1}^{n} M_i$ stochastic gradients, or, in other words, to calculate $x^{1}, \dots, x^{B}$ of the main branch. The same argument can be applied to the next $B$ points of the main branch, and so on.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:local_computation}]
The proof essentially the same as the proof of Theorem~\ref{thm:rennala_computation}.
\end{proof}

