\subsection{\algname{Async-Local SGD}}

\begin{theorem}[\algname{Async-Local SGD}]
  Consider Theorem~\ref{thm:async_plus_local} and its conditions. Under the $h_i$-fixed computation model \eqref{eq:worker-time}, the computational time complexity of \algname{Async-Local SGD} (Alg.~\ref{alg:async_plus_local}) is 
  \begin{align*} 
    \cO\left(\min\limits_{m \in [n]} \left[\left(\frac{1}{m} \sum\limits_{i=1}^{m} \frac{1}{h_i}\right)^{-1} \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{m \varepsilon^2}\right)\right]\right) 
  \end{align*}
  with $B = \max\left\{\left\lceil\frac{\sigma^2}{\varepsilon}\right\rceil, 1\right\}$ and $M = \max\left\{\left\lceil\frac{\sigma^2}{n \varepsilon}\right\rceil, 1\right\}.$
  \label{thm:async_plus_local_comp}
\end{theorem}

\begin{lemma}
  Let us define
  \begin{align}
    T_{\textnormal{AL}}(B,M) \eqdef 2 \min_{m\in[n]} \left[\left(\sum_{i=1}^m \frac{1}{h_i}\right)^{-1} (B + M m)\right]
  \end{align}
  Under the $h_i$-fixed computation model \eqref{eq:worker-time}, the time required to calculate $x^{1}, \dots, x^{B}$ of the main branch is at most $T_{\textnormal{AL}}(B,M)$ seconds, the time required to calculate $x^{B + 1}, \dots, x^{2B}$ is at most $T_{\textnormal{AL}}(B,M)$ seconds, and so on.
  \label{lemma:async_plus_local_comp}
\end{lemma}

\begin{proof}
  Let us fix $B$ and $M \geq 1.$ Note that 
  \begin{align}
    T_{\textnormal{AL}}(B,M) \eqdef 2 \min_{m\in[n]} \left[\left(\sum_{i=1}^m \frac{1}{h_i}\right)^{-1} (B + M m)\right] = 2 \left(\sum_{i=1}^{m^*} \frac{1}{h_i}\right)^{-1} (B + M m^*)
    \label{eq:jyojpUFuuTnWRxYhSd}
  \end{align}
  for some $m^* \in [n],$ which depends on $B$ and $M.$

  For any $k \geq 1$, consider the sequence $x^{k}, \dots, x^{k + B}$ on the main branch. Using a proof by contradiction, assume that it requires more than $T_{\textnormal{AL}}(B,M)$ seconds to calculate $x^{k + 1}, \dots, x^{k + B}.$ Thus, the algorithm can progress up to $x^{k + B - 1}$ after $T_{\textnormal{AL}}(B,M)$ seconds.

  In Algorithm~\ref{alg:async_plus_local}, each worker computes $M$ stochastic gradients and sends their sum to the server. The server then performs the update $w^{k+1} = w^{k} - \gamma \sum_{p = 0}^{M - 1} \nabla f(z^{p}_{i_k}; \eta^{p}_{i_k}),$ which is equivalent to extending the main branch by $M$ points. Therefore, after $t$ seconds, the main branch will have progressed by at least
  \begin{align} 
    \sum_{i=1}^{n} \max\left\{M \left\lfloor\frac{t}{M h_i}\right\rfloor - M, 0\right\}, 
    \label{eq:pjvGDHlntkmUMbtMmnp}
  \end{align}
  points (which is less than $B$ by assumption). This is because worker $i$ requires at most $M h_i$ seconds to compute $M$ stochastic gradients before sending them to the server. Note that during any $B - 1$ consecutive updates on the main branch, the server may ignore $M$ gradients from each worker at most once, because $\delta^k$ can be $\geq B$ at most once during $B - 1$ consecutive updates. This explains the subtraction of $M$ in the formula.

  Substituting $T_{\textnormal{AL}}(B,M)$ to \eqref{eq:pjvGDHlntkmUMbtMmnp},
  \begin{align*}
    &\sum_{i=1}^{n} \max\left\{M \left\lfloor\frac{T_{\textnormal{AL}}(B,M)}{M h_i}\right\rfloor - M, 0\right\} \geq \sum_{i=1}^{m^*} \max\left\{M \left\lfloor\frac{T_{\textnormal{AL}}(B,M)}{M h_i}\right\rfloor - M, 0\right\} \\
    &\geq \sum_{i=1}^{m^*} M \left\lfloor\frac{T_{\textnormal{AL}}(B,M)}{M h_i}\right\rfloor - M m^* \geq \sum_{i=1}^{m^*} \frac{T_{\textnormal{AL}}(B,M)}{h_i} - 2 M m^*
  \end{align*}
  because $\flr{x} \geq x - 1$ for all $x \in \R.$ Using \eqref{eq:jyojpUFuuTnWRxYhSd},
  \begin{align*}
    &\sum_{i=1}^{n} \max\left\{M \left\lfloor\frac{T_{\textnormal{AL}}(B,M)}{M h_i}\right\rfloor - M, 0\right\} \geq 2 (B + M m^*) - 2 M m^* \geq B.
  \end{align*}
  Thus, after $T_{\textnormal{AL}}(B,M)$ seconds, the server collects $B$ stochastic gradients. It is equivalent to calculating $x^{k + 1}, \dots, x^{k + B},$ which contradicts the assumption.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:async_plus_local_comp}]
  Due to Theorem~\ref{thm:async_plus_local}, we know that 
  $\frac{1}{K}\sum_{k=0}^{K-1}\Exp{\|\nabla f(x^k)\|^2} \le \varepsilon$ for
  $$
  K = \left\lceil\frac{4 (B + M - 1) L \Delta}{\varepsilon} + \frac{8 \sigma^2 L \Delta}{\varepsilon^2}\right\rceil.
  $$
  From Lemma~\ref{lemma:rennala}, we know that the time required to calculate $x^{1}, \dots, x^{B}$ of the main branch is at most $T_{\textnormal{AL}}(B,M)$ seconds, the time required to calculate $x^{B + 1}, \dots, x^{2B}$ is at most $T_{\textnormal{AL}}(B,M)$ seconds, and so on. Thus, the total time to find an $\varepsilon$--stationary point is
  \begin{align*}
    \cO\left(T_{\textnormal{AL}}(B,M) \times \frac{K}{B}\right) = \cO\left(T_{\textnormal{AL}}(B,M) \times \left(\frac{L \Delta (B + M)}{B \varepsilon} + \frac{\sigma^2 L \Delta}{B \varepsilon^2}\right)\right).
  \end{align*}
  Using the choice of $B$ and $M,$ we obtain $M \leq B$ and 
  \begin{align*}
    \cO\left(T_{\textnormal{R}}(B) \times \frac{K}{B}\right) 
    &= \cO\left(T_{\textnormal{AL}}(B,M) \times \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{B \varepsilon^2}\right)\right) \\
    &= \cO\left(\min_{m\in[n]} \left[\left(\sum_{i=1}^m \frac{1}{h_i}\right)^{-1} (B + M m)\right] \times \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{B \varepsilon^2}\right)\right) \\
    &= \cO\left(\min_{m\in[n]} \left[\left(\sum_{i=1}^m \frac{1}{h_i}\right)^{-1} (B + M m)\right] \times \frac{L \Delta}{\varepsilon}\right)
  \end{align*}
  because $B \geq \frac{\sigma^2}{\varepsilon}.$ Since $M \leq \frac{\sigma^2}{n \varepsilon} + 1$ and $B \leq \frac{\sigma^2}{\varepsilon} + 1,$
  \begin{align*}
    \cO\left(T_{\textnormal{R}}(B) \times \frac{K}{B}\right) 
    &= \cO\left(\min_{m\in[n]} \left[\left(\sum_{i=1}^m \frac{1}{h_i}\right)^{-1} \left(1 + \frac{\sigma^2}{\varepsilon} + m + \frac{m \sigma^2}{n \varepsilon}\right)\right] \times \frac{L \Delta}{\varepsilon}\right) \\
    &= \cO\left(\min_{m\in[n]} \left[\left(\sum_{i=1}^m \frac{1}{h_i}\right)^{-1} \left(\frac{\sigma^2}{\varepsilon} + m\right)\right] \times \frac{L \Delta}{\varepsilon}\right) \\
    &= \cO\left(\min_{m\in[n]} \left[\left(\frac{1}{m} \sum_{i=1}^m \frac{1}{h_i}\right)^{-1} \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{m \varepsilon^2} \right)\right]\right),
  \end{align*}
  where we use that $m \leq n$ for all $m \in [n].$
\end{proof}

\subsection{\algname{Cycle SGD}}

\begin{theorem}[\algname{Cycle SGD}]
  Consider Theorem~\ref{thm:circular_local_sgd} and its conditions. Under the $h_i$-fixed computation model \eqref{eq:worker-time}, the computational time complexity of \algname{Cycle SGD} (Alg.~\ref{alg:circular_local_sgd}) is
  \begin{align*} 
    \cO\left(\max\limits_{i \in [n]} h_i \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{m \varepsilon^2}\right)\right) 
  \end{align*}
  with $s = \min\left\{\max\left\{\ceil{\frac{n^2\varepsilon}{\sigma^2}}, 1\right\}, n\right\}.$
  \label{thm:circular_local_sgd_computation}
\end{theorem}

\begin{proof}
  According to Theorem~\ref{thm:circular_local_sgd}, 
  $\frac{1}{K}\sum_{k=0}^{K-1}\Exp{\|\nabla f(x^k)\|^2} \le \varepsilon$ for
  $$
  K = \left\lceil\frac{8 n^2 L \Delta}{s \varepsilon} + \frac{8 \sigma^2 L \Delta}{\varepsilon^2}\right\rceil.
  $$

  In the beginning, the algorithm has ``warm-up'', where, in the first iteration of the inner loop, the server collects $s$ stochastic gradients from $s$ workers, which is equivalent to calculating $x^{1}, \dots, x^{s}$ of the main branch. Then, the server collects $2 s$ stochastic gradients from the next group of $s$ workers because they calculated $s$ stochastic in the previous iteration. Starting from the $\ceil{\frac{n}{s}}$\textsuperscript{th} iteration, each group of $s$ workers will return $s \times \ceil{\frac{n}{s}}$ stochastic gradients in every subsequent iteration. Every iterations takes at most $\max\limits_{i \in [n]} h_i$ seconds, because they work in parallel and calculate one stochastic gradient.

  Thus, the total time to calculate $x^1, \dots, x^K$ and find an $\varepsilon$--stationary point is
  \begin{align*}
    &\cO\left(\underbrace{\max\limits_{i \in [n]} h_i \times \ceil{\frac{n}{s}}}_{\textnormal{``warm-up'' phase}} + \max\limits_{i \in [n]} h_i \times \frac{K}{\left(s \times \ceil{\frac{n}{s}}\right)}\right) \\
    &=\cO\left(\max\limits_{i \in [n]} h_i \times \frac{n}{s} + \max\limits_{i \in [n]} h_i \times \left(\frac{n L \Delta}{s \varepsilon} + \frac{\sigma^2 L \Delta}{n \varepsilon^2}\right)\right) \\
    &=\cO\left(\max\limits_{i \in [n]} h_i \times \left(\frac{n L \Delta}{s \varepsilon} + \frac{\sigma^2 L \Delta}{n \varepsilon^2}\right)\right).
  \end{align*}
  because $\frac{L \Delta}{\varepsilon} \geq \frac{1}{2}$ without loss of generality (if $\frac{L \Delta}{\varepsilon} < \frac{1}{2},$ then $x^0$ is an $\varepsilon$--stationary point). Finally,
  \begin{align*}
    &\cO\left(\max\limits_{i \in [n]} h_i \times \left(\frac{n L \Delta}{s \varepsilon} + \frac{\sigma^2 L \Delta}{n \varepsilon^2}\right)\right) = \cO\left(\max\limits_{i \in [n]} h_i \times \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{n \varepsilon^2}\right)\right)
  \end{align*}
  due to the choice of $s.$


