  % \begin{align*}
  %   \cO\left(\max\limits_{i \in [n]} h_i \times \left(\frac{8 n^2 L \Delta}{s \varepsilon} + \frac{8 \sigma^2 L \Delta}{\varepsilon^2}\right)\right)
  % \end{align*}
\end{proof}

