\section{Total Time Complexities of Algorithms under $(h,\tau)$-Fixed Computation Model}
\label{sec:proof_communication}

To compare the communication complexities and the total time complexities of the methods, we now assume that it takes $\tau$ seconds to send a vector from a worker to a parameter server and $\tau$ seconds to send a vector from the server to the workers in the centralized setting. Alternatively, it takes $\tau$ seconds to send a vector to all other workers in the decentralized setting. Moreover, we assume that all workers have the same computational performance: worker $i$ takes $h$ seconds to compute a single stochastic gradient for all $i \in [n]$. We refer to this as the \emph{$(h,\tau)$-fixed computation model}.

Note that it is possible to assume that each worker has its own communication time bound $\tau_i$ and computation time bound $h_i$ and consider \emph{$(h_i,\tau_i)$-fixed computation model} \citep{tyurin2024shadowheart}. However, for simplicity, we assume $\tau_i = \tau$ and $h_i = h$ for all $i \in [n].$ See Section~\ref{sec:proof_communication_general} for a more general case \emph{$(h_i,\tau_i)$-fixed computation model}.
% This assumption is sufficient for comparing the methods.
% In all these theorems, we only consider the total time complexity metric, which is formally a term w.r.t. $\tau$ in the total time complexity required to find $\varepsilon$--stationary point under \emph{$(h,\tau)$-fixed computation model}.

\subsection{\algname{Rennala SGD}}

\begin{theorem}
  Consider Theorem~\ref{thm:rennala} and its conditions. Under $(h,\tau)$-fixed computation model, the total time complexity of \algname{Rennala SGD} (Alg.~\ref{alg:rennala}) is
  \begin{align*} 
    \cO\left(\tau \times \frac{L \Delta}{\varepsilon} + h \times \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{n \varepsilon^2}\right)\right) 
  \end{align*}
  with $B = \max\left\{\left\lceil\frac{\sigma^2}{\varepsilon}\right\rceil, 1\right\}.$
  \label{thm:rennala_comnunication}
\end{theorem}

\begin{proof}
  Note that the communication between of vectors happens every $B$ calculated stochastic gradients, which is equivalent to every $B$ updates of the main branch. Thus the total number of communications is 
  \begin{align*}
    \cO\left(\frac{K}{B}\right),
  \end{align*} 
  where $K = \Theta\left(\frac{B L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{\varepsilon^2}\right)$ due to Theorem~\ref{thm:rennala}. The total communication complexity is
  \begin{align*}
    \cO\left(\tau \times \frac{K}{B}\right) = \cO\left(\frac{\tau}{B} \times \left(\frac{B L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{\varepsilon^2}\right)\right) = \cO\left(\tau \times \frac{L \Delta}{\varepsilon}\right),
  \end{align*}
  where we use the choice of $B.$ It left to take into account the computation factor, which is the same as in Theorem~\ref{thm:rennala_computation}.
  \begin{align*}
    \eqref{eq:MFvzCXtfgWSefbzZ} = \cO\left(h \times \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{n \varepsilon^2}\right)\right)
  \end{align*}
  under the $(h,\tau)$-fixed computation model.
\end{proof}

