\subsection{\algname{Async-Local SGD}}

\begin{theorem}
    % [\algname{Async-Local SGD}]
  \label{thm:async_local_comm}
  Consider Theorem~\ref{thm:async_plus_local} and its conditions. Under $(h,\tau)$-fixed computation model, the total time complexity of \algname{Async-Local SGD} (Alg.~\ref{alg:async_plus_local}) is 
  \begin{align*} 
    \cO\left(\tau \times \frac{L \Delta}{\varepsilon} + h \times \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{n \varepsilon^2}\right)\right) 
  \end{align*}
  with $B = \max\left\{\left\lceil\frac{\sigma^2}{\varepsilon}\right\rceil, 1\right\}$ and $M = \max\left\{\left\lceil\frac{\sigma^2}{n \varepsilon}\right\rceil, 1\right\}.$
\end{theorem}

\begin{proof}
  Under $(h,\tau)$-fixed computation model, all workers send the sums of $M$ stochastic gradients at the same time. According to Theorem~\ref{thm:async_plus_local}, the server should collect 
  \begin{align*}
    \cO\left(\frac{(B + M - 1) L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{\varepsilon^2}\right) = \cO\left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{\varepsilon^2}\right)
  \end{align*}
  stochastic gradients, where the last equality due to the choice of $B$ and due to $B \geq M.$ Since the workers work in parallel and have the equal performance, only $\Theta\left(\min\left\{\frac{B}{M}, n\right\}\right) = \Theta\left(\min\left\{\max\left\{1, \frac{\sigma^2}{M \varepsilon}\right\}, n\right\}\right)$ workers will participate in optimization. Thus, every worker, which participates in optimization, has to send 
  \begin{align*}
    \cO\left(\frac{L \Delta}{\min\left\{\frac{B}{M}, n\right\} \varepsilon} + \frac{\sigma^2 L \Delta}{\min\left\{\frac{B}{M}, n\right\} \varepsilon^2}\right) = \cO\left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{n \varepsilon^2} + \frac{M L \Delta}{\varepsilon}\right)
  \end{align*}
  stochastic gradients. Such a worker calculates $M$ stochastic gradients and only then sends the sum; thus, the maximum number of communications by one worker is
  \begin{align*}
    \cO\left(\frac{L \Delta}{M \varepsilon} + \frac{\sigma^2 L \Delta}{M n \varepsilon^2} + \frac{L \Delta}{\varepsilon}\right).
  \end{align*}
  For every communication, the worker needs to send $M$ stochastic gradients, which takes $h$ seconds, and sends a sum, which takes $\tau$ seconds. Thus, the total time complexity is
  \begin{align}
    \label{eq:uYeRvdpZTBNBlUowOqx}\cO\left(\left(\tau + M h\right) \left(\frac{L \Delta}{M \varepsilon} + \frac{\sigma^2 L \Delta}{M n \varepsilon^2} + \frac{L \Delta}{\varepsilon}\right)\right).
  \end{align}
  Substituting the choice of $M,$ we get the final result.
\end{proof}

