\section{Performance of \algname{Rennala SGD} and \algname{Ringmaster ASGD} on a Quadratic Function}
\label{sec:quadratic}
In this section, we formally prove that the convergence of \algname{Ringmaster ASGD} can be provably faster than \algname{Rennala SGD} due to the frequent model updates.
\begin{theorem}
  Consider \algname{Rennala SGD} (Alg.~\ref{alg:rennala}) and \algname{Ringmaster ASGD} (Alg.~\ref{alg:ringmasternew}) with the optimal parameters $B$ from Sec.~\ref{sec:proof_compt}. 
  Then, there exists a $\mu$-strongly convex function and corresponding stochastic gradients that satisfy Assumptions~\ref{ass:lipschitz_constant}, \ref{ass:lower_bound}, and \ref{ass:stochastic_variance_bounded} with $\nicefrac{\sigma^2}{\varepsilon} \geq n$, such that \algname{Rennala SGD}, with \textbf{any step size} $\gamma,$ requires
  \begin{align*} \widetilde{\Theta}\left({\color{red} \frac{\sigma^2}{n \varepsilon}} \times h \times \frac{L}{\mu}\right) \end{align*}
  seconds to find $\varepsilon$-stationary point under the $h_i$-fixed computation model \eqref{eq:worker-time} with $h_i = h$ for all $i \in [n].$ At the same time, there \textbf{exists a step size} for \algname{Ringmaster ASGD} such that it requires at most
  \begin{align*} \widetilde{\cO}\left(h \times \frac{L}{\mu} \right) \end{align*}
  seconds to find $\varepsilon$-stationary point.
\end{theorem}

\begin{proof}
  In this construction, we take $ f : \mathbb{R}^2 \to \mathbb{R} $ such that 
  \begin{align}
    f(w \equiv (x, y)) = \frac{\mu x^2}{2} + \frac{L y^2}{2}
    \label{eq:wyFdEHmlCZV}
  \end{align}
  for all $ x, y \in \mathbb{R} $. Moreover, we assume that the stochastic gradients $ \nabla f(w; \xi) $ are equal to the true gradient $ \nabla f(w) $; thus, there is no randomness. Note that \emph{a priori}, both methods do not have this information and therefore must choose $ B = \Theta\left(\frac{\sigma^2}{\varepsilon}\right),$ even though the effective variance is zero.

  By the design of \algname{Rennala SGD}, its algorithm is equivalent to the following steps:
  \begin{align}
    w^{t+1} = w^{t} - \gamma B \nabla f(w^{t})
    \label{eq:SkGZWJehKCRTC}
  \end{align}
  because the workers calculate $B$ gradients in every global round. Each round takes 
  \begin{align*}
    \Theta\left(h \times \frac{B}{n}\right) = \Theta\left(h \frac{\sigma^2}{n \varepsilon}\right)
  \end{align*}
  seconds, because the workers have the computation speed $h$ and $B = \Theta\left(\frac{\sigma^2}{\varepsilon}\right)$ in Theorem~\ref{thm:rennala_computation}.

  It is well known that the sequence~\eqref{eq:SkGZWJehKCRTC} requires
  \begin{align*}
    \widetilde{\Theta}\left(\frac{L}{\mu}\right)
  \end{align*}
  iterations (up to logarithmic factors) to find an $\varepsilon$-solution or $\varepsilon$-stationary point with the function \eqref{eq:wyFdEHmlCZV}, even when the step size $\gamma$ can be tuned. Thus, the computational time complexity of \algname{Rennala SGD} is
  \begin{align*}
    \widetilde{\Theta}\left(\frac{\sigma^2}{n \varepsilon} \times h \times \frac{L}{\mu}\right)
  \end{align*}
  seconds.

  Consider now the steps of \algname{Ringmaster ASGD} w.r.t. the first argument $x$. In this algorithm, we take $\gamma = \frac{1}{2 L n}.$ In the case when the computation time is equal for all workers, the first $n$ steps are
  \begin{align*}
    &x^1 = x^0 - \gamma \mu x^0 = (1 - \gamma \mu) x^0, \\
    &x^2 = x^1 - \gamma \mu x^0 = (1 - 2 \gamma \mu) x^0, \\
    &\vdots \\
    &x^n = x^{n - 1} - \gamma \mu x^0 = (1 - n \gamma \mu) x^0,
  \end{align*}
  because the workers start calculating at the same point and return the gradients at the same time. Notice that $0 \leq x^n \leq \dots \leq x^2 \leq x^1.$ Then, the first worker starts calculating at $x^1,$ the seconds worker starts calculating at $x^2,$ and so on. Therefore, the next steps are
  \begin{align*}
    x^{n + 1} &= x^n - \gamma \mu x^{1} \\
    &= (1 - n \gamma \mu) x^0 - \gamma \mu (1 - \gamma \mu) x^0 = (1 - (n + 1) \gamma \mu + \gamma^2 \mu^2) x^0, \\
    x^{n + 2} &= x^{n+1} - \gamma \mu x^{2} \\
    &= (1 - (n + 1) \gamma \mu + \gamma^2 \mu^2) x^0 - \gamma \mu (1 - 2 \gamma \mu) x^0 = (1 - (n + 2) \gamma \mu + 3 \gamma^2 \mu^2) x^0, \\
    &\vdots \\
    x^{2 n} &= x^{2 n - 1} - \gamma \mu x^{n} =  \left(1 - 2 n \gamma \mu + \frac{n(n+1)}{2} \gamma^2 \mu^2\right) x^0 \leq \left(1 - n \gamma \mu\right)^2 x^0.
    % &= \left((1 - n \gamma \mu)^2 - n^2 \gamma^2 \mu^2  + \frac{n(n+1)}{2} \gamma^2 \mu^2\right) x^0.
  \end{align*}
  For $\gamma = \nicefrac{1}{2 L n},$ we have $0 \leq x^{2n} \leq \dots \leq x^{n + 1} \leq x^n \leq \dots \leq x^2 \leq x^1.$
  Using mathematical induction, assume that $0 \leq x^{k n} \leq \dots \leq x^1$ for some $k \geq 1$ and $x^{p n} \leq \left(1 - n \gamma \mu\right)^p x^0$ for all $p \leq k,$ which is true for $k = 2$ (base case). We now prove it for $k + 1.$ \algname{Ringmaster ASGD} calculates $x^{k n + 1}$ as follows:
  \begin{align*}
    x^{k n + 1} &= x^{k n} - \gamma \mu x^{(k - 1) n + 1},
  \end{align*}
  which ensures that $x^{k n + 1} \leq (1 - \gamma \mu) x^{k n} \leq x^{k n}$ and $x^{k n + 1} \geq x^{(k - 1) n + 1} - \gamma \mu x^{(k - 1) n + 1} \geq 0$ for $\gamma = \nicefrac{1}{2 L n}.$ We can continue:
  \begin{align*}
    x^{k n + 2} &= x^{k n + 1} - \gamma \mu x^{(k - 1) n + 2},
  \end{align*}
  which ensures that 
  \begin{align*}
    x^{k n + 2} &\leq x^{k n + 1} - \gamma \mu x^{k n} \leq (1 - \gamma \mu) x^{k n} - \gamma \mu x^{k n} = (1 - 2 \gamma \mu) x^{k n}
  \end{align*}
  and $x^{k n + 2} \geq x^{(k - 1) n + 2} - \gamma \mu x^{(k - 1) n + 2}.$ Continuing, we have
  \begin{align*}
    x^{(k + 1) n} = x^{(k + 1) n - 1} - \gamma \mu x^{k n}.
  \end{align*}
  One can show that
  \begin{align*}
    x^{(k + 1) n} \leq (1 - (n - 1) \gamma \mu) x^{k n} - \gamma \mu x^{k n} \leq (1 - n \gamma \mu) x^{k n},
  \end{align*}
  and $x^{(k + 1) n} \geq x^{k n} - \gamma \mu x^{k n} \geq 0.$ We have proved the next case, $k + 1,$ of the mathematical induction.

  Thus, the sequence $\{x^{p n}\}_{p \geq 2}$ monotonically decreases with the rate 
  \begin{align*}
    x^{p n} \leq \left(1 - n \gamma \mu\right)^p x^0.
  \end{align*}
  Using the same reasoning, we one can show the similar result holds for the second argument $y$ of the function but with $L$ instead of $\mu.$

  Recall that it takes $h$ seconds to calculate $x^{n}$ because $n$ workers work in parallel, it takes $h$ seconds to calculate $x^{2 n},$ and so on. Thus, the computational time complexity of \algname{Ringmaster ASGD} is
  \begin{align*}
    \widetilde{\cO}\left(h \times \frac{L}{\mu}\right)
  \end{align*}
  with step size $\gamma = \frac{1}{2 L n}.$
  % In general, for all $1 \leq j \leq n,$ we have
  % \begin{align*}
  %   x^{k n + j} &= x^{k n + j - 1} - \gamma \mu x^{(k - 1) n + j},
  % \end{align*}
  % \begin{align*}
  %   x^{p n + j} = \left(1 - (p n + j) \gamma \mu + \sum_{i=1}^{p} (-1)^{i+1}\frac{((i - 1) n + j)((i - 1) n + j +1)}{2} \gamma^{i + 1} \mu^{i + 1}\right) x^0
  % \end{align*}
  % for all $0 \leq p \leq k - 1$ and $1 \leq j \leq n.$ We now prove that it holds for $p = k$ and $1 \leq j \leq n.$ The base cases have been verified for $p = 1$ and $p = 2.$ Next, we have
  % \begin{align*}
  %   x^{k n + 1} &= x^{k n + 1} - \gamma \mu x^{(k - 1) n + 1} \\
  %   &= \left(1 - (k n) \gamma \mu + \sum_{i=1}^{k} (-1)^{i+1} \frac{((i - 1) n)((i - 1) n +1)}{2} \gamma^{i + 1} \mu^{i + 1}\right) x^0 \\
  %   &\quad - \gamma \mu \left(1 - ((k - 1) n + 1) \gamma \mu + \sum_{i=1}^{k - 1} (-1)^{i+1} \frac{((i - 1) n + 1)((i - 1) n + 2)}{2} \gamma^{i + 1} \mu^{i + 1}\right) x^0 \\
  %   &= \left(1 - (k n + 1) \gamma \mu + \sum_{i=1}^{k} (-1)^{i+1} \frac{((i - 1) n)((i - 1) n +1)}{2} \gamma^{i + 1} \mu^{i + 1}\right) x^0 \\
  %   &\quad + \left(((k - 1) n + 1) \gamma^2 \mu^2 + \sum_{i=1}^{k - 1} (-1)^{i+2}\frac{((i - 1) n + 1)((i - 1) n + 2)}{2} \gamma^{i + 2} \mu^{i + 2}\right) x^0 \\
  % \end{align*}
  % \begin{align*}
  %   x^{2 k n + 1} &= 2 k n - \gamma \mu x^{1} \\
  % \end{align*}
\end{proof}


